import type { Soru } from "../sorular";

export const P08: Soru[] = [
  { id: "p08-001", k: "Vücut", s: "Yetişkin bir insanın iskeletinde kaç kemik bulunur?", d: "206", y: ["186", "236"], a: "Yetişkin iskeleti genellikle 206 kemikten oluşur. Bazı kişilerde fazladan küçük kemikler bulunabildiği için sayı az da olsa değişebilir." },
  { id: "p08-002", k: "Vücut", s: "İnsan vücudunun en uzun kemiği hangisidir?", d: "Uyluk kemiği", y: ["Kaval kemiği", "Pazı kemiği"], a: "Uyluk kemiği (femur) kalçadan dize uzanır. Vücudun hem en uzun hem de en güçlü kemiklerindendir." },
  { id: "p08-003", k: "Vücut", s: "Vücudun en küçük kemiği nerede bulunur?", d: "Ortakulakta", y: ["Burun ucunda", "Serçe parmakta"], a: "Ortakulaktaki üzengi kemiği yalnızca birkaç milimetre boyundadır ve vücudun en küçük kemiğidir." },
  { id: "p08-004", k: "Vücut", s: "Ortakulaktaki üç küçük kemik hangileridir?", d: "Çekiç, örs, üzengi", y: ["Atlas, aksis, sağrı", "Dil, elmacık, burun"], a: "Bu üç kemik kulak zarındaki titreşimi iç kulağa iletir. Birbirine eklemli küçük bir kaldıraç zinciri gibi çalışırlar." },
  { id: "p08-005", k: "Vücut", s: "Yeni doğan bir bebeğin kemik sayısı yetişkininkine göre nasıldır?", d: "Daha fazladır", y: ["Daha azdır", "Tam olarak aynıdır"], a: "Bebek yaklaşık 270-300 kemik ve kemikleşme merkeziyle doğar. Bunların bir kısmı büyüme sırasında kaynaşır ve sayı 206'ya iner." },
  { id: "p08-006", k: "Vücut", s: "Bebeklerin kafatasındaki yumuşak, zarlı bölgelere halk arasında ne denir?", d: "Bıngıldak", y: ["Gamze", "Benek"], a: "Bıngıldaklar kafatası kemikleri arasındaki zarlı boşluklardır. Doğumda başın biçim değiştirmesine ve beynin büyümesine izin verir, zamanla kapanır." },
  { id: "p08-007", k: "Vücut", s: "Diz kapağı kemiğinin tıptaki adı nedir?", d: "Patella", y: ["Klavikula", "Skapula"], a: "Patella, uyluk kasının kirişi içinde gelişen bir kemiktir. Diz eklemini önden korur ve kasın kaldıraç gücünü artırır." },
  { id: "p08-008", k: "Vücut", s: "Köprücük kemiği vücudun hangi bölgesindedir?", d: "Omuz ile göğüs kemiği arasında", y: ["Kalça ile diz arasında", "Dirsek ile bilek arasında"], a: "Köprücük kemiği (klavikula) kolu gövdeye bağlayan bir destek gibidir. Düşmelerde en sık kırılan kemiklerdendir." },
  { id: "p08-009", k: "Vücut", s: "İnsanda kaç çift kaburga bulunur?", d: "12", y: ["10", "14"], a: "Çoğu insanda 12 çift, yani 24 kaburga vardır. Kadınlarla erkeklerin kaburga sayısı aynıdır." },
  { id: "p08-010", k: "Vücut", s: "Ön uçları göğüs kemiğine hiç bağlanmayan son iki kaburga çiftine ne denir?", d: "Yüzen kaburgalar", y: ["Gerçek kaburgalar", "Boyun kaburgaları"], a: "11. ve 12. kaburga çiftlerinin ön uçları serbesttir. Bu yüzden bunlara yüzen kaburga denir." },
  { id: "p08-011", k: "Vücut", s: "İnsanın boyun bölgesinde kaç omur bulunur?", d: "7", y: ["5", "12"], a: "Boyunda 7 omur vardır. Zürafa da dahil olmak üzere memelilerin neredeyse hepsinde boyun omuru sayısı yedidir." },
  { id: "p08-012", k: "Vücut", s: "Kafatasını taşıyan ilk boyun omurunun adı nedir?", d: "Atlas", y: ["Aksis", "Sakrum"], a: "Adını gökyüzünü omuzlarında taşıyan mitolojik Atlas'tan alır. Başı evet der gibi öne arkaya sallamamızı sağlar." },
  { id: "p08-013", k: "Vücut", s: "Başı hayır der gibi sağa sola çevirmemizi sağlayan ikinci boyun omurunun adı nedir?", d: "Aksis", y: ["Atlas", "Koksiks"], a: "Aksis'in yukarı uzanan dişsi çıkıntısı bir mil gibi çalışır. Atlas omuru bu milin çevresinde döner." },
  { id: "p08-014", k: "Vücut", s: "Bel bölgesinde kaç omur bulunur?", d: "5", y: ["7", "12"], a: "Beş bel omuru vücut ağırlığının büyük kısmını taşır. Bu yüzden omurganın en iri omurlarıdır." },
  { id: "p08-015", k: "Vücut", s: "Sırt (göğüs) bölgesinde kaç omur bulunur?", d: "12", y: ["5", "7"], a: "12 sırt omurunun her birine bir çift kaburga eklemlenir. Kaburgaların 12 çift olması bununla uyumludur." },
  { id: "p08-016", k: "Vücut", s: "Omurganın en alt ucundaki küçük kemik hangisidir?", d: "Kuyruk sokumu kemiği", y: ["Dil kemiği", "Köprücük kemiği"], a: "Kuyruk sokumu (koksiks) birkaç küçük omurun kaynaşmasıyla oluşur. Atalarımızdaki kuyruğun kalıntısı olarak kabul edilir." },
  { id: "p08-017", k: "Vücut", s: "Bir elde kaç kemik bulunur?", d: "27", y: ["17", "37"], a: "Her elde bilekte 8, el tarağında 5 ve parmaklarda 14 kemik vardır. Toplam 27 eder." },
  { id: "p08-018", k: "Vücut", s: "Bir ayakta kaç kemik bulunur?", d: "26", y: ["16", "36"], a: "Ayakta 7 bilek (tarsal), 5 tarak ve 14 parmak kemiği bulunur. Toplam 26 eder." },
  { id: "p08-019", k: "Vücut", s: "Vücuttaki kemiklerin yarısından fazlası nerededir?", d: "Eller ve ayaklarda", y: ["Kafatası ve yüzde", "Omurga ve kaburgalarda"], a: "İki el 54, iki ayak 52 kemik içerir. Bu 106 kemik, toplam 206 kemiğin yarısından fazlasıdır." },
  { id: "p08-020", k: "Vücut", s: "Başparmakta kaç parmak kemiği (falanks) bulunur?", d: "2", y: ["3", "4"], a: "Başparmakta iki, diğer parmakların her birinde üç falanks bulunur." },
  { id: "p08-021", k: "Vücut", s: "Ayağın en büyük kemiği hangisidir?", d: "Topuk kemiği", y: ["Aşık kemiği", "Kamış kemiği"], a: "Topuk kemiği (kalkaneus) yürürken yere ilk değen bölgeyi oluşturur. Baldır kaslarının kirişi de bu kemiğe tutunur." },
  { id: "p08-022", k: "Vücut", s: "Bacağın alt kısmında, önden kolayca hissedilen kalın kemik hangisidir?", d: "Kaval kemiği", y: ["Kamış kemiği", "Uyluk kemiği"], a: "Kaval kemiği (tibia) vücut ağırlığını taşır. Yanındaki ince kamış kemiği (fibula) daha çok kaslara tutunma yeri sağlar." },
  { id: "p08-023", k: "Vücut", s: "Önkolda kaç kemik bulunur?", d: "2", y: ["1", "3"], a: "Önkolda başparmak tarafında döner kemik (radius), serçe parmak tarafında dirsek kemiği (ulna) bulunur." },
  { id: "p08-024", k: "Vücut", s: "Omuz ile dirsek arasındaki üst kol kemiği hangisidir?", d: "Pazı kemiği (humerus)", y: ["Dirsek kemiği (ulna)", "Kürek kemiği (skapula)"], a: "Humerus üstte kürek kemiğiyle omuz eklemini, altta önkol kemikleriyle dirsek eklemini oluşturur." },
  { id: "p08-025", k: "Vücut", s: "Kan hücreleri vücutta esas olarak nerede üretilir?", d: "Kırmızı kemik iliğinde", y: ["Kalpte", "Akciğerlerde"], a: "Alyuvarlar, akyuvarlar ve kan pulcukları kemiklerin içindeki kırmızı kemik iliğinde üretilir." },
  { id: "p08-026", k: "Vücut", s: "Sarı kemik iliği büyük ölçüde neden oluşur?", d: "Yağ dokusundan", y: ["Kas dokusundan", "Kıkırdaktan"], a: "Yetişkinlerde uzun kemiklerin gövdesindeki iliğin çoğu yağ depolayan sarı iliktir." },
  { id: "p08-027", k: "Vücut", s: "Kemiğe sertlik veren mineraller esas olarak hangi elementleri içerir?", d: "Kalsiyum ve fosfor", y: ["Demir ve bakır", "Sodyum ve potasyum"], a: "Kemiğin mineral kısmı büyük ölçüde hidroksiapatit adlı kalsiyum fosfat kristallerinden oluşur." },
  { id: "p08-028", k: "Vücut", s: "Kemiğe esneklik kazandıran ve kırılmasını zorlaştıran protein hangisidir?", d: "Kolajen", y: ["Keratin", "Hemoglobin"], a: "Kolajen lifleri kemiğe esneklik, mineraller sertlik verir. İkisi birlikte kemiği hem sağlam hem dayanıklı yapar." },
  { id: "p08-029", k: "Vücut", s: "Yeni kemik dokusu yapan hücrelere ne ad verilir?", d: "Osteoblast", y: ["Osteoklast", "Eritrosit"], a: "Osteoblastlar kemik yapar, osteoklastlar eski kemiği yıkar. Bu denge sayesinde kemikler yaşam boyu yenilenir." },
  { id: "p08-030", k: "Vücut", s: "Kemiğin dış yüzeyini saran, damar ve sinir içeren zara ne denir?", d: "Kemik zarı (periost)", y: ["Akciğer zarı (plevra)", "Kalp zarı (perikard)"], a: "Kemik zarı kemiğin enine büyümesine ve kırıkların onarılmasına katkı sağlar. Sinirleri sayesinde ağrıya duyarlıdır." },
  { id: "p08-031", k: "Vücut", s: "Dirsek eklemi hangi tür ekleme örnektir?", d: "Menteşe eklem", y: ["Top-yuva eklem", "Kaygan (düz) eklem"], a: "Menteşe eklem, kapı menteşesi gibi esas olarak tek düzlemde bükülüp açılmaya izin verir." },
  { id: "p08-032", k: "Vücut", s: "Omuz ve kalça eklemleri hangi tür eklemdir?", d: "Top-yuva eklem", y: ["Menteşe eklem", "Eksen (döner) eklem"], a: "Yuvarlak kemik başı çukur bir yuvaya oturur. Bu yapı kolun ve bacağın birçok yönde hareket etmesini sağlar." },
  { id: "p08-033", k: "Vücut", s: "Hareketli eklemleri kayganlaştıran sıvıya ne denir?", d: "Eklem sıvısı (sinovyal sıvı)", y: ["Lenf sıvısı", "Beyin omurilik sıvısı"], a: "Eklem sıvısı kıkırdak yüzeyleri kayganlaştırır ve sürtünmeyi azaltır. Ayrıca kıkırdağı besler." },
  { id: "p08-034", k: "Vücut", s: "Kemikleri eklem yerlerinde birbirine bağlayan sağlam yapıya ne denir?", d: "Bağ (ligament)", y: ["Kiriş (tendon)", "Kemik zarı"], a: "Bağlar kemikleri birbirine bağlayarak eklemi sabit tutar. Burkulmalarda en çok zorlanan yapılar bağlardır." },
  { id: "p08-035", k: "Vücut", s: "Kasları kemiklere bağlayan yapıya ne denir?", d: "Kiriş (tendon)", y: ["Bağ (ligament)", "Kıkırdak"], a: "Kirişler kasın çekme kuvvetini kemiğe aktarır. Kolajen liflerinden oluştukları için çok dayanıklıdırlar." },
  { id: "p08-036", k: "Vücut", s: "Baldır kaslarını topuk kemiğine bağlayan kalın kiriş hangisidir?", d: "Aşil tendonu", y: ["Diz kapağı bağı", "Çapraz bağ"], a: "Aşil tendonu vücudun en kalın ve en güçlü tendonudur. Adını topuğundan yaralanan mitolojik kahraman Akhilleus'tan alır." },
  { id: "p08-037", k: "Vücut", s: "Burnun ucu ve kulak kepçesi hangi dokudan yapılmıştır?", d: "Kıkırdak", y: ["Kemik", "Yağ dokusu"], a: "Kıkırdak, kemikten daha esnek bir destek dokusudur. Bu yüzden burun ucu ve kulak kepçesi bükülebilir." },
  { id: "p08-038", k: "Vücut", s: "Başka hiçbir kemikle eklem yapmayan, boyundaki at nalı biçimli kemik hangisidir?", d: "Dil kemiği", y: ["Köprücük kemiği", "Atlas omuru"], a: "Dil kemiği (hiyoid) kas ve bağlarla asılı durur. Dilin ve yutkunmada görev alan kasların tutunma yeridir." },
  { id: "p08-039", k: "Vücut", s: "Kafatasında, çiğneme ve konuşma sırasında hareket eden büyük kemik hangisidir?", d: "Alt çene kemiği", y: ["Alın kemiği", "Elmacık kemiği"], a: "Alt çene (mandibula) şakak kemikleriyle eklem yapar. Kafatasının diğer kemikleri ise birbirine sıkıca kaynaşmıştır." },
  { id: "p08-040", k: "Vücut", s: "Kafatası kemiklerini birbirine bağlayan tırtıklı birleşme çizgilerine ne denir?", d: "Dikiş (sütür)", y: ["Bıngıldak", "Disk"], a: "Dikişler kafatası kemiklerini sıkıca kenetler. Bebeklikte esnektirler, yaşla birlikte giderek kemikleşirler." },
  { id: "p08-041", k: "Vücut", s: "Leğen kemiği kadınlarda genel olarak erkeklere göre nasıldır?", d: "Daha geniş ve yayvan", y: ["Daha dar ve derin", "Daha çok kemikten oluşur"], a: "Kadın leğen kemiği doğuma uygun olarak daha geniş ve yayvandır. Bu fark adli bilimde iskeletten cinsiyet tahmininde kullanılır." },
  { id: "p08-042", k: "Vücut", s: "Kemik yoğunluğunun azalıp kemiklerin kolay kırılır hale gelmesine ne denir?", d: "Kemik erimesi (osteoporoz)", y: ["Kireçlenme (osteoartrit)", "Raşitizm"], a: "Osteoporozda kemiğin iç yapısı seyrekleşir. Kireçlenme ise eklem kıkırdağının aşınmasıdır, farklı bir durumdur." },
  { id: "p08-043", k: "Vücut", s: "Uzun kemiklerde boy uzaması hangi bölgede gerçekleşir?", d: "Büyüme plaklarında", y: ["Kemik iliğinde", "Kemik zarında"], a: "Uzun kemiklerin uçlarına yakın büyüme plakları ergenliğin sonunda kemikleşip kapanır. Böylece boy uzaması durur." },
  { id: "p08-044", k: "Vücut", s: "Yetişkin omurgasının yandan bakıldığında genel biçimi nasıldır?", d: "Hafif S biçiminde", y: ["Dümdüz", "Tek bir C biçiminde"], a: "Boyun, sırt ve bel bölgelerindeki kıvrımlar omurgaya S biçimi verir. Bu kıvrımlar yükü dağıtır ve yaylanma sağlar." },
  { id: "p08-045", k: "Vücut", s: "Göğsün ortasında, kaburgaların önden bağlandığı yassı kemik hangisidir?", d: "Göğüs kemiği", y: ["Kürek kemiği", "Köprücük kemiği"], a: "Göğüs kemiği (sternum) halk arasında iman tahtası olarak da bilinir. Kaburgalar ona kıkırdakla bağlanır." },
  { id: "p08-046", k: "Vücut", s: "Vücudun en büyük eklemi genellikle hangisi kabul edilir?", d: "Diz eklemi", y: ["Omuz eklemi", "Dirsek eklemi"], a: "Diz eklemi uyluk kemiği, kaval kemiği ve diz kapağının birleşmesiyle oluşur. Vücudun en büyük ve en karmaşık eklemlerindendir." },
  { id: "p08-047", k: "Vücut", s: "Omurlar arasında darbe emici yastık görevi gören yapıya ne denir?", d: "Omurlar arası disk", y: ["Eklem kapsülü", "Kemik zarı"], a: "Bu diskler kıkırdaktan oluşur ve ortalarında jel kıvamında bir çekirdek bulunur. Dışarı taşmasına halk arasında fıtık denir." },
  { id: "p08-048", k: "Vücut", s: "Elmacık kemiği yüzün hangi bölgesindedir?", d: "Yanakta, göz altında", y: ["Alında", "Çene ucunda"], a: "Elmacık kemiği yanağın çıkıntısını oluşturur ve göz çukurunun dış alt kenarına katılır." },
  { id: "p08-049", k: "Vücut", s: "Bebeklerde diz kapağı doğumda nasıldır?", d: "Büyük ölçüde kıkırdaktır", y: ["Yetişkindeki kadar serttir", "Henüz hiç oluşmamıştır"], a: "Diz kapağı doğumda çoğunlukla kıkırdaktan oluşur ve çocukluk yıllarında yavaş yavaş kemikleşir." },
  { id: "p08-050", k: "Vücut", s: "Kırık bir kemik iyileşirken kırık hattında oluşan onarım dokusuna ne denir?", d: "Kallus", y: ["Plak", "Kist"], a: "Kırık bölgesinde önce pıhtı, sonra kıkırdak ve kemikten oluşan kallus gelişir. Zamanla düzenli kemik dokusuna dönüşür." },
  { id: "p08-051", k: "Vücut", s: "Kemiklerin uçlarında bulunan, ağ gibi örülmüş hafif kemik dokusuna ne denir?", d: "Süngerimsi kemik", y: ["Sıkı kemik", "Hiyalin kıkırdak"], a: "Süngerimsi kemik ince kemik çubuklarından oluşur. Az malzemeyle yükü dağıtır, aralarında kırmızı ilik bulunabilir." },
  { id: "p08-052", k: "Vücut", s: "Alnı oluşturan kafatası kemiği hangisidir?", d: "Alın kemiği", y: ["Şakak kemiği", "Art kafa kemiği"], a: "Alın kemiği (frontal kemik) alnı ve göz çukurlarının üst kısmını oluşturur." },
  { id: "p08-053", k: "Vücut", s: "Bir kişinin boyu genellikle günün hangi zamanında biraz daha uzundur?", d: "Sabah uyandığında", y: ["Akşam yatmadan önce", "Öğleden sonra"], a: "Gün boyu ayakta kalınca omurlar arası diskler sıkışır. Bu yüzden insan akşamları sabaha göre yaklaşık 1 cm kısa olabilir." },
  { id: "p08-054", k: "Vücut", s: "Kürek kemiği vücudun neresinde bulunur?", d: "Sırtın üst kısmında", y: ["Göğsün önünde", "Kalçanın arkasında"], a: "Kürek kemiği (skapula) üçgen biçimli yassı bir kemiktir. Kol kemiğiyle birlikte omuz eklemini oluşturur." },
  { id: "p08-055", k: "Vücut", s: "Kemikler canlı bir doku mudur?", d: "Evet, hücre ve damar içerir", y: ["Hayır, tamamen mineraldir", "Yalnız bebeklikte canlıdır"], a: "Kemikte kan damarları, sinirler ve sürekli çalışan hücreler bulunur. Bu yüzden kırılan kemik kendini onarabilir." },
  { id: "p08-056", k: "Vücut", s: "Omurganın içinden geçen ve omurlarla korunan yapı hangisidir?", d: "Omurilik", y: ["Yemek borusu", "Aort"], a: "Omurlar üst üste dizilerek bir kanal oluşturur. Omurilik bu kanalın içinde güvenle uzanır." },
  { id: "p08-057", k: "Vücut", s: "Göğüs kafesinin temel görevlerinden biri nedir?", d: "Kalbi ve akciğerleri korumak", y: ["Safra depolamak", "Besinleri sindirmek"], a: "Kaburgalar, göğüs kemiği ve sırt omurları bir kafes oluşturur. Bu kafes ayrıca soluk alıp vermede de hareket eder." },
  { id: "p08-058", k: "Vücut", s: "Ayak bileği ekleminde kaval kemiğinin üzerine oturduğu kemik hangisidir?", d: "Aşık kemiği", y: ["Diz kapağı", "Kürek kemiği"], a: "Aşık kemiği (talus) bacaktan gelen yükü topuk kemiğine ve ayağın önüne aktarır." },
  { id: "p08-059", k: "Vücut", s: "Kuyruk sokumunun hemen üstünde, leğen kemiğinin arka duvarını oluşturan kemik hangisidir?", d: "Sağrı kemiği", y: ["Dil kemiği", "Göğüs kemiği"], a: "Sağrı kemiği (sakrum) beş omurun kaynaşmasıyla oluşan üçgen biçimli bir kemiktir." },
  { id: "p08-060", k: "Vücut", s: "İnsan vücudunda yaklaşık kaç iskelet kası bulunur?", d: "600'den fazla", y: ["Yaklaşık 60", "Yaklaşık 6.000"], a: "Sayım yöntemine göre küçük farklar olsa da vücutta 600'ü aşkın iskelet kası bulunduğu kabul edilir." },
  { id: "p08-061", k: "Vücut", s: "Vücudun en büyük kası genellikle hangisi kabul edilir?", d: "Büyük kalça kası", y: ["Büyük göğüs kası", "Baldır kası"], a: "Büyük kalça kası (gluteus maximus) kalçayı geriye doğru açar. Dik durma, merdiven çıkma ve koşmada önemli rol oynar." },
  { id: "p08-062", k: "Vücut", s: "Vücudun en uzun kası hangisidir?", d: "Terzi kası", y: ["Pazı kası", "Geniş sırt kası"], a: "Terzi kası (sartorius) kalçadan dizin iç yanına çapraz uzanır. Adının bağdaş kurarak dikiş diken terzilerin oturuşundan geldiği söylenir." },
  { id: "p08-063", k: "Vücut", s: "Vücudun en küçük iskelet kası nerede bulunur?", d: "Ortakulakta", y: ["Göz kapağında", "Serçe parmakta"], a: "Üzengi kası (stapedius) yaklaşık bir milimetre boyundadır. Çok yüksek seslerde üzengi kemiğinin titreşimini sınırlar." },
  { id: "p08-064", k: "Vücut", s: "Kas dokusunun üç temel türü hangileridir?", d: "İskelet, düz ve kalp kası", y: ["İskelet, kıkırdak ve kemik", "Düz, yağ ve sinir dokusu"], a: "İskelet kası istemli çalışır. Düz kas iç organların duvarında, kalp kası ise yalnız kalpte bulunur; ikisi de istem dışı çalışır." },
  { id: "p08-065", k: "Vücut", s: "Mide ve bağırsak duvarında hangi tür kas bulunur?", d: "Düz kas", y: ["İskelet kası", "Kalp kası"], a: "Düz kas yavaş ve dalgalar halinde kasılır. Besinleri sindirim kanalı boyunca ilerleten bu kasılmalardır." },
  { id: "p08-066", k: "Vücut", s: "İsteğimizle kontrol edebildiğimiz kas türü hangisidir?", d: "İskelet kası", y: ["Düz kas", "Kalp kası"], a: "Yürümek, konuşmak, el sallamak gibi hareketleri iskelet kaslarıyla yaparız. Bu kaslar sinir sisteminden gelen komutla kasılır." },
  { id: "p08-067", k: "Vücut", s: "Kalp kası hangi özelliğe sahiptir?", d: "Çizgilidir, istem dışı çalışır", y: ["Çizgisizdir, istemle çalışır", "Çizgilidir, istemle çalışır"], a: "Kalp kası mikroskopta iskelet kası gibi çizgili görünür ama irademizle değil, kendi uyarı sistemiyle kasılır." },
  { id: "p08-068", k: "Vücut", s: "Üst kolun önünde bulunan ve dirseği büken kas hangisidir?", d: "Pazı kası (biseps)", y: ["Üç başlı kol kası (triseps)", "Deltoid kas"], a: "Biseps kasıldığında önkolu yukarı çeker ve dirsek bükülür. Önkolun dışa dönmesine de yardım eder." },
  { id: "p08-069", k: "Vücut", s: "Üst kolun arkasında bulunan ve dirseği düzleştiren kas hangisidir?", d: "Üç başlı kol kası (triseps)", y: ["Pazı kası (biseps)", "Trapez kası"], a: "Triseps, bisepsin karşıtıdır. Biri dirseği bükerken diğeri gevşer; düzleştirirken roller değişir." },
  { id: "p08-070", k: "Vücut", s: "Kaslar kemikleri nasıl hareket ettirir?", d: "Kasılıp çekerek", y: ["Uzayıp iterek", "Şişip döndürerek"], a: "Kaslar yalnız çekebilir, itemez. Bu yüzden eklemlerin çevresinde karşıt çiftler halinde çalışırlar." },
  { id: "p08-071", k: "Vücut", s: "Kas kasılmasını sağlayan iki temel protein hangileridir?", d: "Aktin ve miyozin", y: ["Keratin ve kolajen", "İnsülin ve glukagon"], a: "Miyozin başları aktin ipliklerine tutunup onları çeker. Milyonlarca ipliğin birlikte kaymasıyla kas kısalır." },
  { id: "p08-072", k: "Vücut", s: "Kaslar kasılırken doğrudan hangi molekülün enerjisini kullanır?", d: "ATP", y: ["DNA", "Kolesterol"], a: "ATP hücrenin enerji taşıyıcısıdır. Kas hücreleri ATP'yi besinlerden elde edilen enerjiyle sürekli yeniden üretir." },
  { id: "p08-073", k: "Vücut", s: "Üşüdüğümüzde titrememizin vücuda faydası nedir?", d: "Isı üretmek", y: ["Kanı soğutmak", "Terlemeyi artırmak"], a: "Titreme hızlı ve istemsiz kas kasılmalarıdır. Kaslar çalışırken ısı açığa çıkar ve vücut ısınır." },
  { id: "p08-074", k: "Vücut", s: "Kas hücrelerinde oksijen depolayan ve kasa kırmızı renk veren protein hangisidir?", d: "Miyoglobin", y: ["Melanin", "Keratin"], a: "Miyoglobin, hemoglobinin kas içindeki akrabası gibidir. Kasa gereken oksijeni hazır tutar." },
  { id: "p08-075", k: "Vücut", s: "Uyluğun önündeki dört başlı kas (kuadriseps) dizi ne yapar?", d: "Düzleştirir", y: ["Büker", "Kilitleyip sabitler"], a: "Kuadriseps kasıldığında diz eklemi açılır. Ayağa kalkarken, merdiven çıkarken ve top tekmelerken bu kası kullanırız." },
  { id: "p08-076", k: "Vücut", s: "Omzu yuvarlak biçimde saran ve kolu yana kaldıran kas hangisidir?", d: "Deltoid kas", y: ["Trapez kası", "Terzi kası"], a: "Deltoid kas omza yuvarlak görünümünü verir. Adı, Yunan harfi delta gibi üçgen biçimli olmasından gelir." },
  { id: "p08-077", k: "Vücut", s: "Çiğnerken çeneyi güçlü biçimde kapatan yanak kası hangisidir?", d: "Çiğneme kası (masseter)", y: ["Ağız halka kası", "Büyük göğüs kası"], a: "Masseter kası alt çeneyi yukarı çeker. Dişlerinizi sıktığınızda yanağınızın arkasında sertleştiğini hissedebilirsiniz." },
  { id: "p08-078", k: "Vücut", s: "Dil esas olarak hangi dokudan oluşur?", d: "Kas dokusundan", y: ["Kemik ve kıkırdaktan", "Yağ dokusundan"], a: "Dil birçok kasın bir araya gelmesiyle oluşur. Bu sayede konuşma ve yutkunmada çok çeşitli hareketler yapabilir." },
  { id: "p08-079", k: "Vücut", s: "Bir açıklığı çevreleyip büzerek kapatan halka biçimli kaslara ne denir?", d: "Büzgen kas (sfinkter)", y: ["Kiriş (tendon)", "Bağ (ligament)"], a: "Büzgen kaslar mide girişi ve çıkışı, mesane çıkışı gibi yerlerde geçişi denetleyen kapaklar gibi çalışır." },
  { id: "p08-080", k: "Vücut", s: "Bir kasın uzun süre kullanılmaması sonucu küçülmesine ne denir?", d: "Atrofi", y: ["Hipertrofi", "Kramp"], a: "Örneğin alçıdaki bir bacağın kasları birkaç haftada belirgin biçimde incelir. Kas yeniden çalıştırıldıkça toparlanabilir." },
  { id: "p08-081", k: "Vücut", s: "Düzenli kuvvet egzersiziyle kas liflerinin kalınlaşmasına ne denir?", d: "Hipertrofi", y: ["Atrofi", "Fibrozis"], a: "Kuvvet çalışması kas liflerinde daha fazla kasılma proteini yapılmasını uyarır. Böylece lifler kalınlaşır ve kas büyür." },
  { id: "p08-082", k: "Vücut", s: "Ani, istemsiz ve ağrılı kas kasılmasına ne denir?", d: "Kramp", y: ["Atrofi", "Felç"], a: "Kramp genellikle bacak kaslarında görülür. Kas birden kasılır ve gevşeyene kadar ağrı verir." },
  { id: "p08-083", k: "Vücut", s: "Karnın önünde 'baklava' görünümünü oluşturan kas hangisidir?", d: "Düz karın kası", y: ["Geniş sırt kası", "Büyük kalça kası"], a: "Düz karın kası (rectus abdominis) kiriş şeritleriyle bölümlere ayrılır. Görülen dilimler bu şeritlerden kaynaklanır." },
  { id: "p08-084", k: "Vücut", s: "Uyluğun arkasında yer alan ve dizi büken kas grubuna ne denir?", d: "Hamstring kasları", y: ["Kuadriseps", "Deltoid kaslar"], a: "Hamstring kasları dizi büker ve kalçayı geriye açar. Sporcularda en sık zorlanan kas gruplarındandır." },
  { id: "p08-085", k: "Vücut", s: "Parmak ucunda yükselirken topuğu yerden kaldıran kas hangisidir?", d: "Baldır kası", y: ["Terzi kası", "Kuadriseps"], a: "Baldır kası (gastroknemius) Aşil tendonuyla topuğa bağlanır. Kasıldığında topuğu yukarı çeker." },
  { id: "p08-086", k: "Vücut", s: "Sırtın alt ve yan kısmını kaplayan, kolu aşağı ve geriye çeken geniş kas hangisidir?", d: "Geniş sırt kası", y: ["Trapez kası", "Deltoid kas"], a: "Geniş sırt kası (latissimus dorsi) barfiks çekerken ve yüzerken kolu gövdeye doğru çeker." },
  { id: "p08-087", k: "Vücut", s: "Boynun arkasından sırtın üstüne yayılan, omuzları kaldıran yamuk biçimli kas hangisidir?", d: "Trapez kası", y: ["Deltoid kas", "Büyük göğüs kası"], a: "Trapez kası omuz silkerken kürek kemiklerini yukarı kaldırır. Adı yamuk anlamına gelen trapezden gelir." },
  { id: "p08-088", k: "Vücut", s: "Göğsün önünde bulunan ve kolu gövdeye doğru çeken büyük kas hangisidir?", d: "Büyük göğüs kası", y: ["Geniş sırt kası", "Diyafram"], a: "Büyük göğüs kası (pectoralis major) şınav çekerken ve sarılırken kolu öne ve içe doğru hareket ettirir." },
  { id: "p08-089", k: "Vücut", s: "Tüyleri diken diken eden küçük kaslar nerede bulunur?", d: "Derideki kıl köklerinin yanında", y: ["Kemiklerin içinde", "Kalbin duvarında"], a: "Kıl dikici kaslar soğukta ya da heyecanda kasılır, kılı dikleştirir ve deride kabarcıklar oluşturur." },
  { id: "p08-090", k: "Vücut", s: "Mimik kaslarını diğer iskelet kaslarından ayıran özellik nedir?", d: "Bir uçlarıyla deriye tutunmaları", y: ["Düz kas olmaları", "Kalp kası olmaları"], a: "Mimik kaslarının birçoğu deriye bağlanır. Kasıldıklarında deriyi çekerek gülümseme, kaş çatma gibi ifadeleri oluşturur." },
  { id: "p08-091", k: "Vücut", s: "Kalp kası hücrelerini birbirine bağlayan, uyarının hızla yayılmasını sağlayan yapılara ne denir?", d: "Ara diskler", y: ["Büyüme plakları", "Sinir düğümleri"], a: "Ara diskler kalp kası hücrelerini mekanik ve elektriksel olarak birleştirir. Böylece kalp kası bir bütün halinde kasılır." },
  { id: "p08-092", k: "Vücut", s: "İskelet kası hücrelerine uzun yapıları nedeniyle ne ad verilir?", d: "Kas lifi", y: ["Nöron", "Alyuvar"], a: "İskelet kası hücreleri uzun ve çok çekirdeklidir. Birçok hücrenin gelişim sırasında kaynaşmasıyla oluşurlar." },
  { id: "p08-093", k: "Vücut", s: "Yoğun egzersizde oksijen yetersiz kalınca kaslarda enerji üretilirken hangi madde oluşur?", d: "Laktat (laktik asit)", y: ["Üre", "Safra"], a: "Oksijen azken glikoz laktata dönüşür. Ertesi gün hissedilen kas ağrısı ise laktattan değil, kaslardaki küçük hasarlardan kaynaklanır." },
  { id: "p08-094", k: "Vücut", s: "Dudakları büzüp ıslık çalmamızı sağlayan, ağzı çevreleyen kas hangisidir?", d: "Ağız halka kası", y: ["Çiğneme kası", "Trapez kası"], a: "Ağız halka kası (orbicularis oris) dudakları kapatır ve büzer. Konuşmada ve öpücük atarken de görev alır." },
  { id: "p08-095", k: "Vücut", s: "Rotator manşet adı verilen kas ve kiriş grubu hangi eklemi sarar?", d: "Omuz eklemi", y: ["Diz eklemi", "Kalça eklemi"], a: "Rotator manşet dört kasın kirişlerinden oluşur. Kol kemiğinin başını omuz yuvasında tutar ve kolu döndürür." },
  { id: "p08-096", k: "Vücut", s: "Kas kasılmasının başlamasında hangi mineral iyonu kritik rol oynar?", d: "Kalsiyum", y: ["Demir", "İyot"], a: "Sinir uyarısı gelince kas hücresinin içinde depolanan kalsiyum serbest kalır. Bu kalsiyum aktin ile miyozinin etkileşmesini başlatır." },
  { id: "p08-097", k: "Vücut", s: "Omurga boyunca uzanan ve gövdeyi dik tutan kas grubuna ne denir?", d: "Omurga dikleştirici kaslar", y: ["Mimik kasları", "Çiğneme kasları"], a: "Bu kaslar omurganın iki yanında boydan boya uzanır. Ayakta dururken ve eğilip kalkarken gövdeyi dik tutar." },
  { id: "p08-098", k: "Vücut", s: "Gülümserken ağzın köşesini yukarı ve yana çeken kas hangisidir?", d: "Büyük elmacık kası", y: ["Çiğneme kası", "Ağız halka kası"], a: "Büyük elmacık kası (zygomaticus major) elmacık kemiğinden dudak köşesine uzanır ve gülümsemenin ana kasıdır." },
  { id: "p08-099", k: "Vücut", s: "İnsan kalbinin kaç odacığı vardır?", d: "4", y: ["2", "3"], a: "Kalpte iki kulakçık ve iki karıncık bulunur. Sağ yarı akciğerlere, sol yarı tüm vücuda kan pompalar." },
  { id: "p08-100", k: "Vücut", s: "Kalbin kanı toplayan üst odacıklarına ne denir?", d: "Kulakçık", y: ["Karıncık", "Kapakçık"], a: "Kulakçıklar damarlardan gelen kanı toplar ve alttaki karıncıklara aktarır. Asıl pompalama işini karıncıklar yapar." },
  { id: "p08-101", k: "Vücut", s: "Kalbin en kalın duvarlı odacığı hangisidir?", d: "Sol karıncık", y: ["Sağ kulakçık", "Sağ karıncık"], a: "Sol karıncık kanı aort yoluyla bütün vücuda pompalar. Bu yüksek basınca dayanmak için duvarı en kalın odacıktır." },
  { id: "p08-102", k: "Vücut", s: "Kalbin sağ karıncığı kanı nereye pompalar?", d: "Akciğerlere", y: ["Beyne", "Böbreklere"], a: "Sağ karıncık oksijeni azalmış kanı akciğerlere gönderir. Orada kan karbondioksit bırakıp oksijen alır." },
  { id: "p08-103", k: "Vücut", s: "Vücudun en büyük atardamarı hangisidir?", d: "Aort", y: ["Şah damarı", "Akciğer atardamarı"], a: "Aort sol karıncıktan çıkar, göğüste bir yay yapar ve karına iner. Vücuda giden bütün atardamarlar ondan dallanır." },
  { id: "p08-104", k: "Vücut", s: "Vücuttan dönen kanı kalbe getiren en büyük toplardamarlara ne denir?", d: "Ana toplardamarlar", y: ["Aort", "Koroner damarlar"], a: "Üst ve alt ana toplardamarlar (vena kava) vücuttan dönen kanı sağ kulakçığa boşaltır." },
  { id: "p08-105", k: "Vücut", s: "Atardamarlar kanı hangi yöne taşır?", d: "Kalpten dışarıya", y: ["Kalbe doğru", "Yalnız akciğerlerden kalbe"], a: "Atardamarlar kanı kalpten uzaklaştırır, toplardamarlar kalbe getirir. Ayrım kanın oksijenine değil, akış yönüne göre yapılır." },
  { id: "p08-106", k: "Vücut", s: "Oksijeni azalmış kanı taşıyan atardamar hangisidir?", d: "Akciğer atardamarı", y: ["Aort", "Şah damarı"], a: "Akciğer atardamarı kalpten çıktığı için atardamardır ama akciğere oksijen almaya giden kanı taşır." },
  { id: "p08-107", k: "Vücut", s: "Oksijence zengin kanı taşıyan toplardamarlar hangileridir?", d: "Akciğer toplardamarları", y: ["Ana toplardamarlar", "Kapı toplardamarı"], a: "Akciğer toplardamarları akciğerde oksijenlenen kanı sol kulakçığa getirir. Kalbe geldikleri için toplardamar sayılırlar." },
  { id: "p08-108", k: "Vücut", s: "Kan ile dokular arasında madde alışverişinin yapıldığı en ince damarlar hangileridir?", d: "Kılcal damarlar", y: ["Atardamarlar", "Toplardamarlar"], a: "Kılcal damarların duvarı tek hücre kalınlığındadır. Oksijen, besin ve atıklar bu ince duvardan geçer." },
  { id: "p08-109", k: "Vücut", s: "Bacak toplardamarlarında kanın geriye akmasını engelleyen yapılar nelerdir?", d: "Toplardamar kapakçıkları", y: ["Kılcal damarlar", "Kan pulcukları"], a: "Kapakçıklar yalnız kalbe doğru açılır. Bacak kasları kasıldıkça toplardamarları sıkar ve kan yukarı itilir." },
  { id: "p08-110", k: "Vücut", s: "Steteskopla duyulan kalp sesleri esas olarak neden oluşur?", d: "Kalp kapaklarının kapanmasından", y: ["Kanın damarda kaynamasından", "Kalbin kaburgalara çarpmasından"], a: "Birinci ses karıncıklarla kulakçıklar arasındaki kapakların, ikinci ses atardamar çıkışındaki kapakların kapanmasıyla duyulur." },
  { id: "p08-111", k: "Vücut", s: "Sol kulakçık ile sol karıncık arasındaki kapağın adı nedir?", d: "Mitral kapak", y: ["Triküspit kapak", "Akciğer kapağı"], a: "Mitral kapağın iki yaprağı vardır. Sağ taraftaki karşılığı olan triküspit kapak ise üç yapraklıdır." },
  { id: "p08-112", k: "Vücut", s: "Kalbin doğal pili olarak bilinen ve atışları başlatan yapı hangisidir?", d: "Sinüs düğümü", y: ["Aort kapağı", "Kalp zarı"], a: "Sağ kulakçık duvarındaki sinüs düğümü düzenli elektrik uyarıları üretir. Her uyarı kalbin bir kez kasılmasını başlatır." },
  { id: "p08-113", k: "Vücut", s: "Kalp kasını besleyen damarlara ne denir?", d: "Koroner damarlar", y: ["Şah damarları", "Akciğer damarları"], a: "Koroner atardamarlar aortun başlangıcından çıkar ve kalp kasını taç gibi sarar. Adları taç anlamındaki Latince sözcükten gelir." },
  { id: "p08-114", k: "Vücut", s: "Sağlıklı bir yetişkinin dinlenme halindeki kalp hızı genellikle hangi aralıktadır?", d: "Dakikada 60-100 atım", y: ["Dakikada 20-40 atım", "Dakikada 150-200 atım"], a: "Dinlenme kalp hızı genellikle dakikada 60-100 arasındadır. Düzenli spor yapanlarda daha düşük olabilir." },
  { id: "p08-115", k: "Vücut", s: "Kalp bir günde yaklaşık kaç kez atar?", d: "Yaklaşık 100 bin", y: ["Yaklaşık 10 bin", "Yaklaşık 1 milyon"], a: "Dakikada 70 atım günde 100 binin biraz üstüne çıkar. Bir ömür boyunca bu sayı milyarları bulur." },
  { id: "p08-116", k: "Vücut", s: "Kalp dinlenme halinde dakikada yaklaşık ne kadar kan pompalar?", d: "Yaklaşık 5 litre", y: ["Yaklaşık yarım litre", "Yaklaşık 50 litre"], a: "Dinlenmede kalbin dakikalık debisi yaklaşık 5 litredir. Bu, vücuttaki kanın kabaca dakikada bir kez dolaşması demektir." },
  { id: "p08-117", k: "Vücut", s: "Yetişkin bir insanın kalbi kabaca ne büyüklüktedir?", d: "Bir yumruk kadar", y: ["Bir karpuz kadar", "Bir ceviz kadar"], a: "Kalp kabaca sahibinin yumruğu büyüklüğündedir. Yetişkinde ağırlığı genellikle 250-350 gram arasındadır." },
  { id: "p08-118", k: "Vücut", s: "Kalp göğüs boşluğunda nerede bulunur?", d: "İki akciğer arasında, hafif solda", y: ["Göğsün tam sağ tarafında", "Midenin altında"], a: "Kalp göğsün ortasında, göğüs kemiğinin arkasındadır. Ucu sola doğru yöneldiği için atışları solda daha iyi hissedilir." },
  { id: "p08-119", k: "Vücut", s: "Kalbi dıştan saran çift katlı zara ne denir?", d: "Kalp zarı (perikard)", y: ["Akciğer zarı (plevra)", "Kemik zarı (periost)"], a: "Perikardın katları arasındaki az miktarda sıvı, kalbin sürtünmeden atmasını sağlar." },
  { id: "p08-120", k: "Vücut", s: "Tansiyon ölçümündeki büyük sayı neyi gösterir?", d: "Kalp kasılırken damar basıncını", y: ["Kalp gevşerken damar basıncını", "Dakikadaki nabız sayısını"], a: "Büyük sayı sistolik, küçük sayı diyastolik basınçtır. Sağlıklı yetişkinde yaklaşık 120/80 mmHg olarak bilinir." },
  { id: "p08-121", k: "Vücut", s: "Kan basıncı geleneksel olarak hangi birimle ölçülür?", d: "Milimetre cıva (mmHg)", y: ["Desibel (dB)", "Kalori (cal)"], a: "Eski tansiyon aletleri cıva sütunu kullanırdı. Dijital aletler yaygınlaşsa da birim aynı kaldı." },
  { id: "p08-122", k: "Vücut", s: "Oksijeni azalmış kan ne renktedir?", d: "Koyu kırmızı", y: ["Mavi", "Mor"], a: "Kan her zaman kırmızıdır. Toplardamarların deriden mavimsi görünmesi ışığın deride emilip saçılma biçiminden kaynaklanır." },
  { id: "p08-123", k: "Vücut", s: "Bilekte parmakla hissettiğimiz nabız hangi tür damardan gelir?", d: "Atardamardan", y: ["Toplardamardan", "Lenf damarından"], a: "Her kalp atışında atardamar duvarı basınç dalgasıyla genişler. Bilekte hissedilen bu dalgadır." },
  { id: "p08-124", k: "Vücut", s: "1628'de kan dolaşımını ayrıntılı olarak tanımlayan hekim kimdir?", d: "William Harvey", y: ["Louis Pasteur", "Alexander Fleming"], a: "İngiliz hekim William Harvey kanın kalp tarafından pompalanıp vücutta kapalı bir devrede dolaştığını gösterdi." },
  { id: "p08-125", k: "Vücut", s: "Kalpten akciğerlere gidip yeniden kalbe dönen kan yoluna ne denir?", d: "Küçük dolaşım", y: ["Büyük dolaşım", "Kapı dolaşımı"], a: "Küçük (akciğer) dolaşımında kan oksijenlenir. Büyük dolaşımda ise kalpten tüm vücuda gidip geri döner." },
  { id: "p08-126", k: "Vücut", s: "Kalbin elektriksel etkinliğini kaydeden teste ne denir?", d: "EKG", y: ["EEG", "EMG"], a: "Elektrokardiyografi (EKG), kalbin her atışında oluşan elektrik dalgalarını deriye yapıştırılan elektrotlarla kaydeder." },
  { id: "p08-127", k: "Vücut", s: "Kalbin sağ ve sol yarısını birbirinden ayıran duvara ne denir?", d: "Kalp bölmesi (septum)", y: ["Diyafram", "Kalp zarı"], a: "Septum oksijenli ve oksijeni azalmış kanın karışmasını önler. Böylece iki dolaşım birbirinden ayrı kalır." },
  { id: "p08-128", k: "Vücut", s: "Sindirim organlarından gelen kanı karaciğere taşıyan damar hangisidir?", d: "Kapı toplardamarı", y: ["Aort", "Akciğer atardamarı"], a: "Bağırsaktan emilen besinler kapı toplardamarıyla önce karaciğere gider. Karaciğer bunları işleyip depolar." },
  { id: "p08-129", k: "Vücut", s: "Vücuttaki kan damarlarının toplam uzunluğu yaklaşık ne kadar olarak tahmin edilir?", d: "Yaklaşık 100 bin km", y: ["Yaklaşık 100 km", "Yaklaşık 10 milyon km"], a: "Bu değer bir tahmindir ve uzunluğun büyük kısmını kılcal damarlar oluşturur. Uç uca eklense Dünya'nın çevresini birkaç kez dolanırdı." },
  { id: "p08-130", k: "Vücut", s: "Boynun yan tarafında nabzın kolayca hissedildiği damar hangisidir?", d: "Şah damarı (karotis)", y: ["Boyun toplardamarı", "Aort"], a: "Şah damarları beyne ve yüze kan taşır. Boynun iki yanında, gırtlağın hemen yanında atışları hissedilir." },
  { id: "p08-131", k: "Vücut", s: "Atardamarların duvarı toplardamarlarınkine göre nasıldır?", d: "Daha kalın ve esnek", y: ["Daha ince ve gevşek", "Aynı kalınlıkta"], a: "Atardamarlar kalbin yüksek basıncına maruz kalır. Kalın, kaslı ve esnek duvarları bu basınca dayanır." },
  { id: "p08-132", k: "Vücut", s: "Dalağın kanla ilgili başlıca görevlerinden biri nedir?", d: "Yaşlı alyuvarları ayıklamak", y: ["Safra üretmek", "İnsülin salgılamak"], a: "Dalak karnın sol üst bölümündedir. Yıpranmış alyuvarları kandan ayıklar ve bağışıklıkta da görev alır." },
  { id: "p08-133", k: "Vücut", s: "Lenf damarlarının başlıca görevi nedir?", d: "Doku sıvısını kana geri taşımak", y: ["Kanı kalpten pompalamak", "Akciğere hava taşımak"], a: "Kılcal damarlardan dokulara sızan sıvının bir kısmı lenf damarlarıyla toplanır ve toplardamarlar yoluyla kana döner." },
  { id: "p08-134", k: "Vücut", s: "Anne karnındaki bebekte iki kulakçık arasında bulunan açıklığa ne denir?", d: "Oval delik", y: ["Bıngıldak", "Göbek bağı"], a: "Bebek akciğerleriyle soluk almadığı için kan oval delikten akciğerleri atlar. Doğumdan sonra bu açıklık genellikle kapanır." },
  { id: "p08-135", k: "Vücut", s: "Kalbin gevşeyip kanla dolduğu evreye ne denir?", d: "Diyastol", y: ["Sistol", "Fibrilasyon"], a: "Her kalp döngüsü kasılma (sistol) ve gevşeme (diyastol) evrelerinden oluşur. Karıncıklar diyastolde kanla dolar." },
  { id: "p08-136", k: "Vücut", s: "Kan basıncının sürekli olarak normalden yüksek olmasına ne denir?", d: "Hipertansiyon", y: ["Hipotansiyon", "Hipoglisemi"], a: "Hipertansiyon çoğu zaman belirti vermez. Bu yüzden düzenli tansiyon ölçümü önemlidir." },
  { id: "p08-137", k: "Vücut", s: "Yetişkin bir insanın vücudunda yaklaşık kaç litre kan bulunur?", d: "Yaklaşık 5 litre", y: ["Yaklaşık 1 litre", "Yaklaşık 15 litre"], a: "Kan hacmi vücut büyüklüğüne göre değişir ama yetişkinde genellikle 4,5-5,5 litre arasındadır." },
  { id: "p08-138", k: "Vücut", s: "Kanın, hücrelerin içinde yüzdüğü sıvı kısmına ne denir?", d: "Plazma", y: ["Lenf", "Safra"], a: "Plazma açık sarı renkli bir sıvıdır. Besinleri, hormonları, tuzları ve atıkları taşır." },
  { id: "p08-139", k: "Vücut", s: "Plazma, kanın hacminin yaklaşık ne kadarını oluşturur?", d: "Yarısından biraz fazlasını", y: ["Onda birini", "Tamamına yakınını"], a: "Kanın yaklaşık yüzde 55'i plazma, geri kalanı büyük ölçüde alyuvarlardır." },
  { id: "p08-140", k: "Vücut", s: "Kan plazmasının büyük bölümü neden oluşur?", d: "Sudan", y: ["Yağdan", "Proteinden"], a: "Plazmanın yaklaşık yüzde 90'ından fazlası sudur. Geri kalanında proteinler, tuzlar, besinler ve hormonlar bulunur." },
  { id: "p08-141", k: "Vücut", s: "Alyuvarlara kırmızı rengini veren molekül hangisidir?", d: "Hemoglobin", y: ["Melanin", "Klorofil"], a: "Hemoglobin oksijene bağlanan bir proteindir. Oksijenle bağlandığında açık kırmızı, oksijeni azken koyu kırmızı görünür." },
  { id: "p08-142", k: "Vücut", s: "Hemoglobinde oksijeni bağlayan element hangisidir?", d: "Demir", y: ["Bakır", "Magnezyum"], a: "Her hemoglobin molekülünde dört demir atomu bulunur ve her biri bir oksijen molekülü bağlayabilir." },
  { id: "p08-143", k: "Vücut", s: "İnsanda olgun alyuvarların dikkat çeken özelliği nedir?", d: "Çekirdekleri yoktur", y: ["Çok çekirdeklidirler", "Yıldız biçimlidirler"], a: "Alyuvarlar olgunlaşırken çekirdeklerini atar. Böylece içlerinde hemoglobine daha çok yer kalır." },
  { id: "p08-144", k: "Vücut", s: "Bir alyuvarın ortalama ömrü ne kadardır?", d: "Yaklaşık 120 gün", y: ["Yaklaşık 1 gün", "Yaklaşık 10 yıl"], a: "Yaklaşık dört ay dolaşan alyuvar yıpranınca dalak ve karaciğerde ayıklanır. Yerine kemik iliği sürekli yenilerini üretir." },
  { id: "p08-145", k: "Vücut", s: "Alyuvarlar nasıl bir biçime sahiptir?", d: "İki yüzü çukur disk", y: ["Kusursuz küre", "Uzun iplik"], a: "Bu biçim yüzey alanını artırarak gaz alışverişini kolaylaştırır. Alyuvarın esnekliği de dar kılcallardan geçmesini sağlar." },
  { id: "p08-146", k: "Vücut", s: "Kanın pıhtılaşmasında görev alan hücre parçaları hangileridir?", d: "Kan pulcukları (trombosit)", y: ["Alyuvarlar", "Akyuvarlar"], a: "Damar yaralanınca kan pulcukları yaraya yapışıp bir tıkaç oluşturur ve pıhtılaşma zincirini başlatır." },
  { id: "p08-147", k: "Vücut", s: "Kan pıhtısında ağ örerek hücreleri tutan protein hangisidir?", d: "Fibrin", y: ["Keratin", "Miyozin"], a: "Pıhtılaşma sırasında kandaki fibrinojen fibrine dönüşür. Fibrin iplikleri bir ağ oluşturur ve kan hücrelerini hapseder." },
  { id: "p08-148", k: "Vücut", s: "ABO kan grubu sistemini 1901'de keşfeden bilim insanı kimdir?", d: "Karl Landsteiner", y: ["Robert Koch", "Gregor Mendel"], a: "Avusturyalı Karl Landsteiner bu keşifle güvenli kan naklinin önünü açtı ve 1930'da Nobel Ödülü aldı." },
  { id: "p08-149", k: "Vücut", s: "Alyuvar naklinde genel verici olarak bilinen kan grubu hangisidir?", d: "0 Rh negatif", y: ["AB Rh pozitif", "A Rh negatif"], a: "0 Rh negatif alyuvarlarda A, B ve Rh antijenleri bulunmaz. Bu yüzden acil durumlarda çoğu alıcıya verilebilir." },
  { id: "p08-150", k: "Vücut", s: "Alyuvar naklinde genel alıcı olarak bilinen kan grubu hangisidir?", d: "AB Rh pozitif", y: ["0 Rh negatif", "B Rh pozitif"], a: "AB Rh pozitif kişilerin plazmasında anti-A ve anti-B antikoru yoktur. Bu yüzden her ABO grubundan alyuvar alabilirler." },
  { id: "p08-151", k: "Vücut", s: "Rh faktörü adını nereden alır?", d: "Rhesus maymunundan", y: ["Bir hekimin soyadından", "Rodos adasından"], a: "Bu antijen ilk kez rhesus maymunlarıyla yapılan deneylerde fark edildi. Adı da buradan geldi." },
  { id: "p08-152", k: "Vücut", s: "AB grubundaki birinin alyuvarlarında hangi ABO antijenleri bulunur?", d: "A ve B", y: ["Yalnız A", "Yalnız B"], a: "Kan grubu adı alyuvardaki antijeni gösterir. A grubunda A, B grubunda B, AB grubunda ikisi birden bulunur; 0 grubunda ikisi de yoktur." },
  { id: "p08-153", k: "Vücut", s: "0 grubundaki birinin plazmasında hangi antikorlar bulunur?", d: "Anti-A ve anti-B", y: ["Yalnız anti-A", "Hiç ABO antikoru yok"], a: "0 grubunun alyuvarlarında A ve B antijeni yoktur, plazmasında ise her ikisine karşı antikor bulunur." },
  { id: "p08-154", k: "Vücut", s: "Dünya genelinde en yaygın ABO kan grubu hangisidir?", d: "0", y: ["AB", "B"], a: "Dünya genelinde en yaygın grup 0'dır. Oranlar ülkeden ülkeye değişir; bazı ülkelerde A grubu daha yaygındır." },
  { id: "p08-155", k: "Vücut", s: "Dünya genelinde en nadir görülen ABO kan grubu hangisidir?", d: "AB", y: ["0", "A"], a: "AB grubu dünya nüfusunun küçük bir bölümünde görülür. Oran bölgeden bölgeye farklılık gösterir." },
  { id: "p08-156", k: "Vücut", s: "Bir insanın kan grubunu ne belirler?", d: "Anne ve babadan gelen genler", y: ["Çocuklukta yenen besinler", "Doğulan mevsim"], a: "Kan grubu kalıtımla belirlenir. Her ebeveynden bir ABO geni gelir ve bu iki genin birleşimi grubu belirler." },
  { id: "p08-157", k: "Vücut", s: "Kanın pıhtılaşmasında güçlük çekilen kalıtsal hastalık hangisidir?", d: "Hemofili", y: ["Anemi", "Hipertansiyon"], a: "Hemofilide pıhtılaşma faktörlerinden biri eksiktir. Gen X kromozomunda bulunduğu için erkeklerde çok daha sık görülür." },
  { id: "p08-158", k: "Vücut", s: "Kandaki hemoglobin ya da alyuvar miktarının normalden az olmasına ne denir?", d: "Anemi (kansızlık)", y: ["Hemofili", "Lösemi"], a: "Anemide dokulara yeterince oksijen taşınamaz. Halsizlik, solukluk ve çabuk yorulma görülebilir." },
  { id: "p08-159", k: "Vücut", s: "Sağlıklı bir insanın kan pH değeri nasıldır?", d: "Hafif bazik (yaklaşık 7,4)", y: ["Güçlü asidik (yaklaşık 2)", "Güçlü bazik (yaklaşık 11)"], a: "Kan pH'ı 7,35-7,45 gibi dar bir aralıkta tutulur. Akciğerler ve böbrekler bu dengeyi korur." },
  { id: "p08-160", k: "Vücut", s: "Böbreklerde üretilen ve alyuvar yapımını uyaran hormon hangisidir?", d: "Eritropoietin", y: ["İnsülin", "Adrenalin"], a: "Kandaki oksijen azalınca böbrekler eritropoietin salgılar. Bu hormon kemik iliğinin daha çok alyuvar üretmesini sağlar." },
  { id: "p08-161", k: "Vücut", s: "Karbonmonoksit gazı kanda neden tehlikelidir?", d: "Hemoglobine oksijenden sıkı bağlanır", y: ["Kanı hemen pıhtılaştırır", "Alyuvarları patlatır"], a: "Karbonmonoksit hemoglobine oksijenden yüzlerce kat daha güçlü bağlanır. Böylece kan dokulara oksijen taşıyamaz hale gelir." },
  { id: "p08-162", k: "Vücut", s: "Morluklar iyileşirken renginin morumsudan sarı-yeşile dönmesinin nedeni nedir?", d: "Hemoglobinin parçalanması", y: ["Derideki melaninin artması", "Kasların kasılması"], a: "Deri altına sızan kandaki hemoglobin parçalanırken yeşilimsi ve sarımsı pigmentlere dönüşür. Renk değişimi bundandır." },
  { id: "p08-163", k: "Vücut", s: "Yaşlı alyuvarların yıkımıyla oluşan ve fazlası sarılığa yol açan sarı pigment hangisidir?", d: "Bilirubin", y: ["Melanin", "Karoten"], a: "Bilirubin karaciğerde işlenip safrayla atılır. Kanda birikirse deri ve göz akı sararır." },
  { id: "p08-164", k: "Vücut", s: "Kan plazmasında en bol bulunan protein hangisidir?", d: "Albümin", y: ["Hemoglobin", "Kolajen"], a: "Karaciğerde üretilen albümin, sıvının damar içinde kalmasına yardım eder ve birçok maddeyi taşır." },
  { id: "p08-165", k: "Vücut", s: "Akyuvarların başlıca görevi nedir?", d: "Vücudu mikroplara karşı savunmak", y: ["Oksijen taşımak", "Pıhtı oluşturmak"], a: "Akyuvarlar kanla bütün vücudu dolaşır. Gerektiğinde damar duvarından çıkarak dokulardaki mikroplarla savaşır." },
  { id: "p08-166", k: "Vücut", s: "Kanda sayıca en çok bulunan hücreler hangileridir?", d: "Alyuvarlar", y: ["Akyuvarlar", "Kan pulcukları"], a: "Bir damla kandaki alyuvar sayısı akyuvarlardan yüzlerce kat fazladır. Vücuttaki hücrelerin sayıca büyük bölümü alyuvardır." },
  { id: "p08-167", k: "Vücut", s: "Kan, vücut ağırlığının yaklaşık ne kadarını oluşturur?", d: "Yaklaşık %7-8", y: ["Yaklaşık %1", "Yaklaşık %25"], a: "70 kilogramlık bir yetişkinde bu oran yaklaşık 5 litre kana karşılık gelir." },
  { id: "p08-168", k: "Vücut", s: "Kan pıhtılaştıktan sonra ayrılan berrak sıvıya ne denir?", d: "Serum", y: ["Lenf", "Safra"], a: "Serum, pıhtılaşma proteinleri tükenmiş plazmadır. Birçok laboratuvar testi serumda yapılır." },
  { id: "p08-169", k: "Vücut", s: "Rh uyuşmazlığı hangi durumda söz konusu olabilir?", d: "Anne Rh negatif, bebek Rh pozitifse", y: ["Anne Rh pozitif, bebek Rh negatifse", "İkisi de Rh pozitifse"], a: "Rh negatif anne, Rh pozitif bebeğin kanına karşı antikor geliştirebilir. Bu durum hamilelik takibinde kontrol edilir." },
  { id: "p08-170", k: "Vücut", s: "Kan şekeri denildiğinde kandaki hangi şeker kastedilir?", d: "Glikoz", y: ["Laktoz", "Sakaroz"], a: "Glikoz hücrelerin başlıca yakıtıdır. Kandaki düzeyi insülin ve glukagon hormonlarıyla dar bir aralıkta tutulur." },
  { id: "p08-171", k: "Vücut", s: "Kandaki oksijenin büyük kısmı nasıl taşınır?", d: "Hemoglobine bağlı olarak", y: ["Plazmada çözünmüş olarak", "Akyuvarların içinde"], a: "Oksijenin yüzde 98 kadarı alyuvarlardaki hemoglobine bağlı taşınır. Plazmada çözünen miktar çok azdır." },
  { id: "p08-172", k: "Vücut", s: "Kandaki karbondioksitin büyük kısmı hangi biçimde taşınır?", d: "Bikarbonat olarak", y: ["Saf gaz kabarcığı olarak", "Kan pulcuklarına bağlı"], a: "Karbondioksitin çoğu alyuvarlardaki bir enzim yardımıyla bikarbonata dönüşür ve plazmada taşınır. Akciğerde yeniden gaza döner." },
  { id: "p08-173", k: "Vücut", s: "Sağ akciğer kaç lobdan oluşur?", d: "3", y: ["2", "4"], a: "Sağ akciğer üç, sol akciğer iki lobludur. Loblar birbirinden derin yarıklarla ayrılır." },
  { id: "p08-174", k: "Vücut", s: "Sol akciğerin sağ akciğerden biraz küçük olmasının nedeni nedir?", d: "Kalbe yer açması", y: ["Mideye yer açması", "Karaciğere yer açması"], a: "Kalbin ucu sola yöneldiği için sol akciğerde kalbin oturduğu bir çentik bulunur. Bu yüzden sol akciğer biraz küçüktür." },
  { id: "p08-175", k: "Vücut", s: "Akciğerlerde gaz alışverişinin gerçekleştiği küçük keseciklere ne denir?", d: "Alveol", y: ["Bronş", "Villus"], a: "Alveollerin duvarı çok incedir ve kılcal damarlarla sarılıdır. Oksijen kana, karbondioksit havaya buradan geçer." },
  { id: "p08-176", k: "Vücut", s: "İki akciğerde toplam yaklaşık kaç alveol bulunur?", d: "Yüz milyonlarca", y: ["Birkaç bin", "Birkaç yüz"], a: "Tahminler yaklaşık 300-500 milyon arasındadır. Bu sayede akciğerlerin gaz alışverişi yüzeyi çok büyüktür." },
  { id: "p08-177", k: "Vücut", s: "Soluk borusunun büzüşmeden açık kalmasını sağlayan yapı nedir?", d: "C biçimli kıkırdak halkalar", y: ["Kemik halkalar", "Yağ yastıkları"], a: "Kıkırdak halkaların açık ucu arkadaki yemek borusuna bakar. Böylece yutulan lokma yemek borusunda rahatça ilerler." },
  { id: "p08-178", k: "Vücut", s: "Ses tellerinin bulunduğu organ hangisidir?", d: "Gırtlak", y: ["Yutak", "Bronş"], a: "Gırtlaktaki ses telleri, akciğerden gelen havayla titreşerek ses üretir. Gerginlikleri değiştikçe sesin inceliği değişir." },
  { id: "p08-179", k: "Vücut", s: "Yutkunurken soluk borusunun girişini kapatan yapı hangisidir?", d: "Gırtlak kapağı (epiglot)", y: ["Küçük dil", "Diyafram"], a: "Gırtlak kapağı yutkunma sırasında aşağı kapanır. Böylece lokma soluk borusuna değil yemek borusuna gider." },
  { id: "p08-180", k: "Vücut", s: "Soluk almada görev alan en önemli kas hangisidir?", d: "Diyafram", y: ["Büyük göğüs kası", "Düz karın kası"], a: "Diyafram göğüs ve karın boşluğunu ayıran kubbe biçimli bir kastır. Sakin soluk almanın büyük kısmını o yapar." },
  { id: "p08-181", k: "Vücut", s: "Diyafram kasılıp düzleştiğinde ne olur?", d: "Soluk alınır", y: ["Soluk verilir", "Öksürülür"], a: "Diyafram aşağı inince göğüs boşluğu genişler, akciğerlerdeki basınç düşer ve hava içeri dolar." },
  { id: "p08-182", k: "Vücut", s: "Soluduğumuz havanın yaklaşık ne kadarı oksijendir?", d: "Yaklaşık %21", y: ["Yaklaşık %50", "Yaklaşık %78"], a: "Atmosfer havasının yaklaşık yüzde 78'i azot, yüzde 21'i oksijendir. Kalanı argon, karbondioksit ve diğer gazlardır." },
  { id: "p08-183", k: "Vücut", s: "Dışarı verdiğimiz havada yaklaşık ne kadar oksijen bulunur?", d: "Yaklaşık %16", y: ["Hiç bulunmaz", "Yaklaşık %50"], a: "Her solukta oksijenin yalnız bir kısmı kana geçer. Verilen havada hâlâ önemli miktarda oksijen kalır, karbondioksit ise artar." },
  { id: "p08-184", k: "Vücut", s: "Dinlenen bir yetişkin dakikada yaklaşık kaç kez soluk alır?", d: "12-20 kez", y: ["2-4 kez", "60-80 kez"], a: "Yetişkinde dinlenme solunum hızı genellikle dakikada 12-20 arasındadır. Bebeklerde bu hız daha yüksektir." },
  { id: "p08-185", k: "Vücut", s: "Soluk alma isteğini en güçlü biçimde tetikleyen durum hangisidir?", d: "Kanda karbondioksitin artması", y: ["Midenin dolması", "Vücut ısısının düşmesi"], a: "Soluk tutunca hissedilen dayanılmaz istek esas olarak kanda biriken karbondioksitten kaynaklanır." },
  { id: "p08-186", k: "Vücut", s: "Akciğerleri saran çift katlı zara ne denir?", d: "Akciğer zarı (plevra)", y: ["Kemik zarı (periost)", "Kalp zarı (perikard)"], a: "Plevranın iki katı arasındaki ince sıvı tabakası, akciğerlerin göğüs duvarına sürtünmeden kaymasını sağlar." },
  { id: "p08-187", k: "Vücut", s: "Alveollerin içini kaplayıp büzüşmelerini önleyen madde hangisidir?", d: "Sürfaktan", y: ["Mukus", "Safra"], a: "Sürfaktan yüzey gerilimini azaltır. Gebeliğin son haftalarında yeterince üretilir; erken doğan bebeklerde eksik olabilir." },
  { id: "p08-188", k: "Vücut", s: "Hıçkırık neden olur?", d: "Diyaframın istemsiz kasılmasıyla", y: ["Ses tellerinin kopmasıyla", "Midenin delinmesiyle"], a: "Diyafram ani kasılınca hava hızla içeri çekilir. Ses telleri aniden kapanınca o tanıdık hık sesi çıkar." },
  { id: "p08-189", k: "Vücut", s: "Burundaki kıllar ve mukusun soluk almadaki görevi nedir?", d: "Havayı süzmek", y: ["Havayı soğutmak", "Oksijen üretmek"], a: "Burun havayı süzer, ısıtır ve nemlendirir. Toz ve mikroplar mukusa yapışarak akciğerlere ulaşmadan tutulur." },
  { id: "p08-190", k: "Vücut", s: "Solunum yollarında mukusu yukarı doğru süpüren mikroskobik tüycüklere ne denir?", d: "Siller", y: ["Villuslar", "Alveoller"], a: "Siller dalga gibi çırpınarak mukusu boğaza doğru taşır. Mukus orada yutulur ya da öksürükle atılır." },
  { id: "p08-191", k: "Vücut", s: "Âdem elması olarak bilinen boyundaki çıkıntı nedir?", d: "Gırtlaktaki tiroid kıkırdağı", y: ["Dil kemiği", "Bir lenf düğümü"], a: "Ergenlikte gırtlak büyür ve tiroid kıkırdağı öne doğru çıkar. Erkeklerde genellikle daha belirgindir." },
  { id: "p08-192", k: "Vücut", s: "Ergenlikte erkeklerin sesinin kalınlaşmasının başlıca nedeni nedir?", d: "Ses tellerinin uzayıp kalınlaşması", y: ["Akciğerlerin büyümesi", "Dilin kalınlaşması"], a: "Testosteronun etkisiyle gırtlak büyür ve ses telleri uzar. Daha uzun ve kalın teller daha yavaş titreşir, ses kalınlaşır." },
  { id: "p08-193", k: "Vücut", s: "Sakin bir solukta akciğerlere yaklaşık ne kadar hava girer?", d: "Yaklaşık yarım litre", y: ["Yaklaşık 5 litre", "Yaklaşık 50 mililitre"], a: "Sakin solunumda her nefeste yaklaşık 500 mililitre hava alınır. Derin bir nefeste bu miktar birkaç litreye çıkabilir." },
  { id: "p08-194", k: "Vücut", s: "Alveollerde oksijenin kana geçmesi hangi yolla olur?", d: "Difüzyon", y: ["Aktif pompalama", "Sindirim"], a: "Gazlar yoğun oldukları yerden az oldukları yere kendiliğinden yayılır. Alveoldeki oksijen bu yolla kana geçer." },
  { id: "p08-195", k: "Vücut", s: "Akciğerler soluk alırken nasıl genişler?", d: "Göğüs boşluğu genişleyince pasif olarak", y: ["Kendi kaslarıyla kasılarak", "Kalbin itmesiyle"], a: "Akciğerlerde iskelet kası yoktur. Diyafram ve kaburgalar arası kaslar göğüs boşluğunu büyütünce akciğerler genişler." },
  { id: "p08-196", k: "Vücut", s: "Soluk borusu göğüs boşluğunda hangi dallara ayrılır?", d: "Sağ ve sol ana bronşlar", y: ["Alveoller", "Akciğer toplardamarları"], a: "Ana bronşlar akciğerlere girer ve ağaç dalları gibi giderek incelen bronşçuklara ayrılır." },
  { id: "p08-197", k: "Vücut", s: "Hapşırmanın temel işlevi nedir?", d: "Burundaki tahriş edicileri atmak", y: ["Akciğere fazladan hava çekmek", "Kalp ritmini düzenlemek"], a: "Hapşırma bir reflekstir. Burun içi tahriş olunca hava güçlü biçimde dışarı atılarak toz ve mikroplar temizlenir." },
  { id: "p08-198", k: "Vücut", s: "Burnun çevresinde kafatası kemiklerinin içindeki hava boşluklarına ne denir?", d: "Sinüsler", y: ["Alveoller", "Bıngıldaklar"], a: "Sinüsler kafatasını hafifletir ve sese tını katar. İçleri mukus salgılayan bir zarla kaplıdır." },
  { id: "p08-199", k: "Vücut", s: "Hem havanın hem de besinlerin geçtiği ortak boğaz bölümüne ne denir?", d: "Yutak", y: ["Gırtlak", "Yemek borusu"], a: "Yutak (farinks) ağız ve burun boşluğunun arkasındadır. Aşağıda gırtlağa ve yemek borusuna ayrılır." },
  { id: "p08-200", k: "Vücut", s: "Sindirim vücudun neresinde başlar?", d: "Ağızda", y: ["Midede", "İnce bağırsakta"], a: "Dişler besini parçalar, tükürükteki enzimler de nişastayı sindirmeye başlar. Yani sindirim daha ilk lokmada başlar." },
  { id: "p08-201", k: "Vücut", s: "Tükürükte bulunan ve nişastayı sindirmeye başlayan enzim hangisidir?", d: "Amilaz", y: ["Pepsin", "Lipaz"], a: "Amilaz nişastayı daha küçük şeker parçalarına ayırır. Ekmeği uzun süre çiğneyince hafif tatlılaşması bundandır." },
  { id: "p08-202", k: "Vücut", s: "Bir yetişkin günde yaklaşık ne kadar tükürük üretir?", d: "Yaklaşık 1-1,5 litre", y: ["Yaklaşık 50 mililitre", "Yaklaşık 10 litre"], a: "Tükürük gün boyu üretilir, yemek sırasında artar. Ağzı nemli tutar, lokmayı kayganlaştırır ve yutmayı kolaylaştırır." },
  { id: "p08-203", k: "Vücut", s: "En büyük tükürük bezi hangisidir?", d: "Kulak altı bezi", y: ["Dil altı bezi", "Çene altı bezi"], a: "Kulak altı bezi (parotis) kulağın önünde ve altında bulunur. Kabakulakta şişen bez budur." },
  { id: "p08-204", k: "Vücut", s: "Sindirim kanalında besinleri ileri iten dalga biçimindeki kas kasılmalarına ne denir?", d: "Peristaltizm", y: ["Difüzyon", "Osmoz"], a: "Peristaltizmde kas halkaları sırayla kasılıp gevşer. Bu dalga, besini diş macunu tüpünden sıkar gibi ileri iter." },
  { id: "p08-205", k: "Vücut", s: "Baş aşağı dururken yutulan su mideye ulaşabilir mi?", d: "Evet, kas dalgaları sayesinde", y: ["Hayır, yer çekimi gerekir", "Yalnız katı besinler ulaşır"], a: "Yemek borusu besini yer çekimine değil, kendi kas kasılmalarına güvenerek taşır. Astronotlar da uzayda bu sayede yutkunabilir." },
  { id: "p08-206", k: "Vücut", s: "Midede salgılanan güçlü asit hangisidir?", d: "Hidroklorik asit", y: ["Sülfürik asit", "Sitrik asit"], a: "Mide asidi pH'ı 1,5-3,5 civarına düşürür. Proteinlerin sindirimine yardım eder ve besinle gelen mikropların çoğunu öldürür." },
  { id: "p08-207", k: "Vücut", s: "Mide kendi asidiyle neden sindirilmez?", d: "Koruyucu mukus tabakası sayesinde", y: ["Asit çok zayıf olduğu için", "Mide duvarı kemikten olduğu için"], a: "Mide duvarı kalın bir mukus tabakası ve asidi nötrleyen bikarbonatla korunur. Bu hücreler de sık sık yenilenir." },
  { id: "p08-208", k: "Vücut", s: "Midede proteinleri sindirmeye başlayan enzim hangisidir?", d: "Pepsin", y: ["Amilaz", "Laktaz"], a: "Pepsin asidik ortamda çalışır ve uzun protein zincirlerini daha kısa parçalara böler." },
  { id: "p08-209", k: "Vücut", s: "Midede kısmen sindirilmiş, bulamaç kıvamındaki besin karışımına ne denir?", d: "Kimus", y: ["Safra", "Lenf"], a: "Mide besini asit ve enzimlerle karıştırarak kimusa dönüştürür. Kimus azar azar ince bağırsağa geçer." },
  { id: "p08-210", k: "Vücut", s: "Midenin ince bağırsağa açıldığı yerdeki büzgen kasa ne denir?", d: "Pilor (mide kapısı)", y: ["Gırtlak kapağı", "Küçük dil"], a: "Pilor büzgeni kimusun ince bağırsağa azar azar geçmesini sağlar. Böylece bağırsak bir anda fazla yüklenmez." },
  { id: "p08-211", k: "Vücut", s: "Sindirim kanalının en uzun bölümü hangisidir?", d: "İnce bağırsak", y: ["Kalın bağırsak", "Yemek borusu"], a: "İnce bağırsak birkaç metre uzunluğundadır. Adındaki ince sözcüğü uzunluğu değil, kalın bağırsaktan dar olmasını anlatır." },
  { id: "p08-212", k: "Vücut", s: "İnce bağırsağın mideden sonra gelen ilk bölümü hangisidir?", d: "Onikiparmak bağırsağı", y: ["Kör bağırsak", "Düz bağırsak"], a: "Adı, uzunluğunun yan yana konmuş on iki parmak eni kadar olduğu düşünülmesinden gelir. Safra ve pankreas salgıları buraya dökülür." },
  { id: "p08-213", k: "Vücut", s: "İnce bağırsağın iç yüzeyindeki parmak benzeri küçük çıkıntılara ne denir?", d: "Villus", y: ["Alveol", "Sil"], a: "Villuslar ve üzerlerindeki mikrovilluslar emilim yüzeyini çok büyütür. Besinler bu yüzeyden kana ve lenfe geçer." },
  { id: "p08-214", k: "Vücut", s: "Besinlerin büyük kısmı sindirim kanalının neresinde emilir?", d: "İnce bağırsakta", y: ["Midede", "Kalın bağırsakta"], a: "Sindirimin tamamlandığı ve besinlerin çoğunun kana geçtiği yer ince bağırsaktır." },
  { id: "p08-215", k: "Vücut", s: "Kalın bağırsağın temel görevi nedir?", d: "Su ve tuzları geri emmek", y: ["Proteinleri sindirmek", "Safra üretmek"], a: "Kalın bağırsak sindirilmeyen kalıntılardan suyu geri emer. Böylece dışkı katılaşır ve vücut su kaybetmez." },
  { id: "p08-216", k: "Vücut", s: "Apandis sindirim kanalının hangi bölümüne bağlıdır?", d: "Kör bağırsağa", y: ["Mideye", "Onikiparmak bağırsağına"], a: "Apandis, kalın bağırsağın başlangıcı olan kör bağırsaktan uzanan parmak biçimli küçük bir çıkıntıdır." },
  { id: "p08-217", k: "Vücut", s: "Vücudun en büyük iç organı hangisidir?", d: "Karaciğer", y: ["Mide", "Dalak"], a: "Yetişkinde yaklaşık 1,5 kilogram gelen karaciğer en ağır iç organdır. Aynı zamanda vücudun en büyük bezidir." },
  { id: "p08-218", k: "Vücut", s: "Safrayı üreten organ hangisidir?", d: "Karaciğer", y: ["Safra kesesi", "Pankreas"], a: "Safra karaciğerde üretilir, safra kesesinde depolanıp yoğunlaştırılır ve yemekten sonra onikiparmak bağırsağına boşaltılır." },
  { id: "p08-219", k: "Vücut", s: "Safra kesesinin görevi nedir?", d: "Safrayı depolamak", y: ["Safrayı üretmek", "İnsülin salgılamak"], a: "Safra kesesi karaciğerin altında duran küçük bir kesedir. Yağlı bir yemekten sonra kasılarak safrayı bağırsağa gönderir." },
  { id: "p08-220", k: "Vücut", s: "Safra yağların sindirimine nasıl yardım eder?", d: "Yağı küçük damlacıklara ayırır", y: ["Yağı şekere dönüştürür", "Yağı doğrudan kana taşır"], a: "Safra, deterjanın yağı dağıtması gibi yağı küçük damlacıklara böler. Böylece yağ sindiren enzimler daha kolay çalışır." },
  { id: "p08-221", k: "Vücut", s: "Hem sindirim enzimleri hem de insülin üreten organ hangisidir?", d: "Pankreas", y: ["Dalak", "Böbrek"], a: "Pankreas enzimlerini bir kanalla bağırsağa, insülin gibi hormonlarını ise doğrudan kana verir." },
  { id: "p08-222", k: "Vücut", s: "Yağları sindiren enzime ne ad verilir?", d: "Lipaz", y: ["Amilaz", "Pepsin"], a: "Lipaz yağları yağ asitleri ve gliserole parçalar. En çok pankreastan salgılanıp ince bağırsakta çalışır." },
  { id: "p08-223", k: "Vücut", s: "Karaciğerin dikkat çeken özelliklerinden biri nedir?", d: "Bir kısmı alınınca yeniden büyüyebilmesi", y: ["Kalp gibi ritmik kasılması", "Ses üretebilmesi"], a: "Karaciğer kaybettiği dokuyu büyük ölçüde yerine koyabilen bir organdır. Canlı vericiden karaciğer nakli bu sayede mümkündür." },
  { id: "p08-224", k: "Vücut", s: "Karaciğer karın boşluğunun hangi bölümündedir?", d: "Sağ üst bölümünde", y: ["Sol alt bölümünde", "Göbeğin altında"], a: "Karaciğer diyaframın hemen altında, büyük kısmı sağ kaburgaların arkasında yer alır." },
  { id: "p08-225", k: "Vücut", s: "Glikozun karaciğer ve kaslarda depolanan biçimine ne denir?", d: "Glikojen", y: ["Selüloz", "Kolesterol"], a: "Glikojen birçok glikoz biriminden oluşur. Kan şekeri düşünce karaciğer glikojeni parçalayıp kana glikoz verir." },
  { id: "p08-226", k: "Vücut", s: "Mide karın boşluğunun hangi bölümündedir?", d: "Sol üst bölümünde", y: ["Sağ alt bölümünde", "Göbeğin altında"], a: "Mide diyaframın altında, çoğunlukla sol tarafta yer alır. Doluluğuna göre biçimi ve büyüklüğü değişir." },
  { id: "p08-227", k: "Vücut", s: "Karından gelen guruldama sesleri genellikle neden kaynaklanır?", d: "Gaz ve sıvının bağırsakta hareketinden", y: ["Mide duvarının yırtılmasından", "Kalp atışlarından"], a: "Sindirim kanalı kasılırken içindeki gaz ve sıvı yer değiştirir. Bu hareket guruldama olarak duyulur; aç karnına daha belirgindir." },
  { id: "p08-228", k: "Vücut", s: "Geğirmenin başlıca nedeni nedir?", d: "Mideye yutulan havanın çıkması", y: ["Akciğerdeki havanın boşalması", "Safranın yukarı taşması"], a: "Yemek yerken ve gazlı içecek içerken mideye hava ve gaz girer. Fazlası yemek borusundan yukarı çıkarak geğirmeye yol açar." },
  { id: "p08-229", k: "Vücut", s: "Yutkunurken besinin burun boşluğuna kaçmasını önleyen yapılar hangileridir?", d: "Yumuşak damak ve küçük dil", y: ["Gırtlak kapağı ve ses telleri", "Diyafram ve kaburgalar"], a: "Yutkunurken yumuşak damak ve küçük dil yukarı kalkarak burun boşluğunun arka girişini kapatır." },
  { id: "p08-230", k: "Vücut", s: "Dışkıya kahverengi rengini veren pigmentler neyden oluşur?", d: "Bilirubinden", y: ["Klorofilden", "Melaninden"], a: "Safrayla bağırsağa gelen bilirubin, bağırsak bakterileri tarafından kahverengi pigmentlere dönüştürülür." },
  { id: "p08-231", k: "Vücut", s: "Mide asidinin sindirim dışındaki önemli bir görevi nedir?", d: "Mikropları öldürmek", y: ["Yağ depolamak", "Su emmek"], a: "Mide asidi besinle gelen bakteri ve diğer mikropların büyük kısmını etkisiz hale getirir." },
  { id: "p08-232", k: "Vücut", s: "Göğüste yanma hissi veren reflü nedir?", d: "Mide içeriğinin yemek borusuna kaçması", y: ["Kalp kasının yorulması", "Akciğerin iltihaplanması"], a: "Yemek borusunun alt ucundaki büzgen tam kapanmazsa asit yukarı kaçar. Yanma göğüste hissedilse de sorun kalpte değildir." },
  { id: "p08-233", k: "Vücut", s: "Kalın bağırsakta yaşayan bakteriler ne yapar?", d: "Lifleri parçalar, bazı vitaminleri üretir", y: ["Tümüyle zararlı mikroplardır", "Yalnızca proteinleri sindirir"], a: "Bağırsak bakterileri sindirilemeyen lifleri parçalar ve K vitamini gibi bazı vitaminleri üretir. Çoğu bize yararlıdır." },
  { id: "p08-234", k: "Vücut", s: "Kalın bağırsağın, dışkıyı atılana kadar biriktiren son bölümüne ne denir?", d: "Düz bağırsak (rektum)", y: ["Kör bağırsak", "Onikiparmak bağırsağı"], a: "Rektum dolunca gerilir ve tuvalet ihtiyacı hissedilir. Dışkı anüsten büzgen kaslar denetiminde atılır." },
  { id: "p08-235", k: "Vücut", s: "Alkol ve birçok zararlı maddeyi zararsız hale getiren başlıca organ hangisidir?", d: "Karaciğer", y: ["Dalak", "Safra kesesi"], a: "Karaciğer hücreleri birçok ilacı, alkolü ve zararlı maddeyi enzimlerle parçalayıp atılabilir hale getirir." },
  { id: "p08-236", k: "Vücut", s: "Proteinler sindirildiğinde hangi yapı taşlarına ayrılır?", d: "Amino asitler", y: ["Glikoz", "Yağ asitleri"], a: "Vücut amino asitleri emer ve onları kendi proteinlerini yapmak için yeniden birleştirir." },
  { id: "p08-237", k: "Vücut", s: "Nişasta tamamen sindirildiğinde hangi şekere dönüşür?", d: "Glikoz", y: ["Laktoz", "Fruktoz"], a: "Nişasta binlerce glikoz biriminden oluşan bir zincirdir. Sindirim bu zinciri tek tek glikozlara ayırır." },
  { id: "p08-238", k: "Vücut", s: "Pankreas sindirim enzimlerini nereye boşaltır?", d: "Onikiparmak bağırsağına", y: ["Mideye", "Kalın bağırsağa"], a: "Pankreas sıvısı enzimlerin yanında bikarbonat da içerir. Bu, mideden gelen asidi nötrler." },
  { id: "p08-239", k: "Vücut", s: "Mide iç yüzeyini kaplayan hücreler ne sıklıkla yenilenir?", d: "Birkaç günde bir", y: ["Birkaç yılda bir", "Hiç yenilenmez"], a: "Asidik ortamda yıpranan mide yüzey hücreleri birkaç günde bir yenileriyle değiştirilir." },
  { id: "p08-240", k: "Vücut", s: "Yetişkinde yemek borusu yaklaşık ne uzunluktadır?", d: "Yaklaşık 25 cm", y: ["Yaklaşık 2 metre", "Yaklaşık 3 cm"], a: "Yemek borusu yutaktan başlar, göğüs boşluğundan geçer ve diyaframı delerek mideye bağlanır." },
  { id: "p08-241", k: "Vücut", s: "Süt şekerini (laktoz) sindiren enzim hangisidir?", d: "Laktaz", y: ["Lipaz", "Pepsin"], a: "Laktaz ince bağırsakta üretilir. Birçok insanda yetişkinlikte azalır; bu durum laktoz intoleransı olarak bilinir." },
  { id: "p08-242", k: "Vücut", s: "İnsanın kendi enzimleriyle sindiremediği bitki maddesi hangisidir?", d: "Selüloz", y: ["Nişasta", "Sakaroz"], a: "Selüloz bitki hücre duvarının ana maddesidir. Sindirilmeden ilerler ve lif olarak bağırsak hareketlerine katkı sağlar." },
  { id: "p08-243", k: "Vücut", s: "İnce bağırsakta emilen yağlar önce hangi damarlara geçer?", d: "Lenf damarlarına", y: ["Doğrudan böbrek damarlarına", "Safra kanallarına"], a: "Yağlar villusların içindeki lenf kılcallarına geçer. Lenf yoluyla taşınıp göğüste büyük bir toplardamara karışır." },
  { id: "p08-244", k: "Vücut", s: "Dişlerle çiğneme hangi tür sindirime örnektir?", d: "Mekanik sindirim", y: ["Kimyasal sindirim", "Emilim"], a: "Mekanik sindirim besini fiziksel olarak küçültür. Bu, enzimlerin çalışacağı yüzeyi artırarak kimyasal sindirimi hızlandırır." },
  { id: "p08-245", k: "Vücut", s: "İnce bağırsaktan kalın bağırsağa geçişte bulunan kapak hangisidir?", d: "İleosekal kapak", y: ["Mitral kapak", "Gırtlak kapağı"], a: "İleosekal kapak ince bağırsağın son kısmını kör bağırsağa bağlar ve içeriğin geri kaçmasını sınırlar." },
  { id: "p08-246", k: "Vücut", s: "Böbrekler vücudun neresinde bulunur?", d: "Bel hizasında, karnın arka duvarında", y: ["Göğüs kafesinin önünde", "Kasık bölgesinde"], a: "Böbrekler omurganın iki yanında, alt kaburgaların hemen altında ve karın organlarının arkasında yer alır." },
  { id: "p08-247", k: "Vücut", s: "Böbrekler hangi biçime benzer?", d: "Fasulye", y: ["Yıldız", "Küp"], a: "Böbrekler fasulye biçimlidir ve her biri yaklaşık bir yumruk büyüklüğündedir. İç kenardaki çukurdan damarlar ve üreter girip çıkar." },
  { id: "p08-248", k: "Vücut", s: "Böbreğin kanı süzüp idrar oluşturan işlevsel birimine ne denir?", d: "Nefron", y: ["Alveol", "Nöron"], a: "Her nefron kanı süzen bir yumak ve süzüntüyü işleyen uzun bir kanalcıktan oluşur." },
  { id: "p08-249", k: "Vücut", s: "Bir böbrekte yaklaşık kaç nefron bulunur?", d: "Yaklaşık 1 milyon", y: ["Yaklaşık 1.000", "Yaklaşık 1 milyar"], a: "Sayı kişiden kişiye değişse de bir böbrekte ortalama 1 milyon civarında nefron bulunduğu kabul edilir." },
  { id: "p08-250", k: "Vücut", s: "Böbrekler günde yaklaşık ne kadar sıvı süzer?", d: "Yaklaşık 180 litre", y: ["Yaklaşık 2 litre", "Yaklaşık 2.000 litre"], a: "Böbrekler kandan günde yaklaşık 180 litre süzüntü çıkarır. Bunun çok büyük kısmı geri emilir." },
  { id: "p08-251", k: "Vücut", s: "Sağlıklı bir yetişkin günde yaklaşık ne kadar idrar üretir?", d: "Yaklaşık 1-2 litre", y: ["Yaklaşık 20 litre", "Yaklaşık 50 mililitre"], a: "İdrar miktarı içilen sıvıya ve terlemeye göre değişir. Süzülen 180 litrenin yalnız yüzde 1 kadarı idrar olur." },
  { id: "p08-252", k: "Vücut", s: "Böbreklerde süzülen sıvının büyük kısmına ne olur?", d: "Kana geri emilir", y: ["İdrar olarak atılır", "Terle dışarı çıkar"], a: "Süzüntüdeki su, glikoz ve tuzların çoğu kanalcıklarda geri emilir. Böylece yararlı maddeler kaybedilmez." },
  { id: "p08-253", k: "Vücut", s: "Böbrekte kanı süzen kılcal damar yumağına ne denir?", d: "Glomerül", y: ["Villus", "Alveol"], a: "Glomerülde kan basıncı suyu ve küçük molekülleri süzer. Kan hücreleri ve büyük proteinler damar içinde kalır." },
  { id: "p08-254", k: "Vücut", s: "Böbrekte glomerülü çevreleyen ve süzüntüyü toplayan yapıya ne denir?", d: "Bowman kapsülü", y: ["Eklem kapsülü", "Kalp zarı"], a: "Bowman kapsülü kadeh gibi glomerülü sarar. Süzülen sıvı buradan nefronun kanalcıklarına geçer." },
  { id: "p08-255", k: "Vücut", s: "İdrarı böbreklerden mesaneye taşıyan kanala ne denir?", d: "Üreter", y: ["Üretra", "Aort"], a: "Her böbrekten bir üreter çıkar. Duvarındaki kasların dalga biçimli kasılmalarıyla idrar mesaneye iner." },
  { id: "p08-256", k: "Vücut", s: "İdrarı mesaneden dışarı atan kanala ne denir?", d: "Üretra", y: ["Üreter", "Kolon"], a: "Üretra mesanenin altından başlar. Erkeklerde kadınlara göre çok daha uzundur." },
  { id: "p08-257", k: "Vücut", s: "İdrarın atılana kadar biriktiği organ hangisidir?", d: "Mesane", y: ["Safra kesesi", "Mide"], a: "Mesane esnek, kaslı bir kesedir. Doldukça genişler ve duvarındaki gerilme idrara çıkma isteği yaratır." },
  { id: "p08-258", k: "Vücut", s: "İdrara sarı rengini veren pigment hangisidir?", d: "Ürokrom", y: ["Melanin", "Klorofil"], a: "Ürokrom, hemoglobin yıkımıyla ilişkili bir pigmenttir. Az su içildiğinde idrar yoğunlaşır ve rengi koyulaşır." },
  { id: "p08-259", k: "Vücut", s: "Proteinlerin yıkımından oluşan ve idrarla atılan başlıca azotlu atık hangisidir?", d: "Üre", y: ["Glikoz", "Kolesterol"], a: "Amino asitler parçalanınca zehirli amonyak oluşur. Vücut onu daha zararsız olan üreye çevirip idrarla atar." },
  { id: "p08-260", k: "Vücut", s: "Üre vücutta hangi organda üretilir?", d: "Karaciğerde", y: ["Böbrekte", "Mesanede"], a: "Karaciğer amonyağı üreye dönüştürür. Böbrekler ise üreyi kandan süzüp idrarla dışarı atar." },
  { id: "p08-261", k: "Vücut", s: "Böbreklerden salgılanan ve kan basıncının düzenlenmesinde rol oynayan enzim hangisidir?", d: "Renin", y: ["Pepsin", "Amilaz"], a: "Kan basıncı düşünce böbrekler renin salgılar. Bu, damarları daraltan ve tuz-su tutulumunu artıran bir zinciri başlatır." },
  { id: "p08-262", k: "Vücut", s: "Antidiüretik hormon (ADH) idrar miktarını nasıl etkiler?", d: "Azaltır", y: ["Artırır", "Etkilemez"], a: "ADH böbreklerin suyu geri emmesini artırır. Vücut susuz kaldığında daha çok salgılanır ve idrar koyulaşır." },
  { id: "p08-263", k: "Vücut", s: "Alkol neden idrar miktarını artırır?", d: "ADH salgısını baskıladığı için", y: ["Böbrekleri büyüttüğü için", "Mesaneyi küçülttüğü için"], a: "ADH azalınca böbrekler suyu geri ememez ve daha çok idrar üretilir. Bu da vücudun su kaybetmesine yol açar." },
  { id: "p08-264", k: "Vücut", s: "Tek sağlıklı böbrekle yaşamak mümkün müdür?", d: "Evet, genellikle mümkündür", y: ["Hayır, asla mümkün değildir", "Yalnız çocuklukta mümkündür"], a: "Tek böbrek iki böbreğin işini büyük ölçüde üstlenebilir. Böbrek bağışı yapan birçok kişi sağlıklı yaşamını sürdürür." },
  { id: "p08-265", k: "Vücut", s: "Kalbin pompaladığı kanın yaklaşık ne kadarı böbreklere gider?", d: "Yaklaşık beşte biri", y: ["Yaklaşık yüzde biri", "Yarısından fazlası"], a: "Böbrekler vücut ağırlığının küçük bir kısmını oluşturur ama dinlenmede kalp debisinin yaklaşık yüzde 20-25'ini alır." },
  { id: "p08-266", k: "Vücut", s: "Yetişkin bir insanın vücut ağırlığının yaklaşık ne kadarı sudur?", d: "Yaklaşık %60", y: ["Yaklaşık %20", "Yaklaşık %90"], a: "Oran yaşa ve vücut yapısına göre değişir. Bebeklerde daha yüksek, yaşlılarda ve yağ oranı yüksek kişilerde daha düşüktür." },
  { id: "p08-267", k: "Vücut", s: "1954'te yapılan ilk başarılı böbrek nakli kimler arasında gerçekleşti?", d: "Tek yumurta ikizleri", y: ["Anne ve kızı", "İki yabancı"], a: "Boston'da yapılan nakilde verici ve alıcı tek yumurta ikizleriydi. Genetik olarak aynı oldukları için organ reddedilmedi." },
  { id: "p08-268", k: "Vücut", s: "Böbrekleri çalışmayan hastalarda kanın bir makineyle temizlenmesine ne denir?", d: "Diyaliz", y: ["Transfüzyon", "Anestezi"], a: "Diyaliz makinesi kanı yarı geçirgen bir zardan geçirerek atıkları ve fazla suyu ayırır. Böbreğin süzme işini taklit eder." },
  { id: "p08-269", k: "Vücut", s: "Akciğerler boşaltımda hangi atığı vücuttan uzaklaştırır?", d: "Karbondioksit", y: ["Üre", "Safra"], a: "Hücrelerin enerji üretirken oluşturduğu karbondioksit kanla akciğerlere taşınır ve soluk verirken atılır." },
  { id: "p08-270", k: "Vücut", s: "Terle vücuttan başlıca neler atılır?", d: "Su ve tuzlar", y: ["Kan hücreleri", "Safra ve enzimler"], a: "Ter büyük ölçüde sudur ve sodyum klorür gibi tuzlar içerir. Az miktarda üre gibi atıklar da terle atılır." },
  { id: "p08-271", k: "Vücut", s: "Böbrekler hangi vitaminin etkin biçime dönüşmesinde son adımı gerçekleştirir?", d: "D vitamini", y: ["C vitamini", "A vitamini"], a: "Deride oluşan D vitamini karaciğerde ve ardından böbrekte işlenerek etkin hormon biçimine dönüşür." },
  { id: "p08-272", k: "Vücut", s: "Böbrek taşları neyin birikmesiyle oluşur?", d: "İdrardaki mineral kristallerinin", y: ["Kopan kemik parçalarının", "Yutulan küçük taşların"], a: "İdrardaki kalsiyum gibi maddeler yoğunlaşınca kristaller oluşup büyüyebilir. Taşların çoğu kalsiyum içerir." },
  { id: "p08-273", k: "Vücut", s: "Sağ böbrek genellikle sol böbreğe göre nerede bulunur?", d: "Biraz daha aşağıda", y: ["Çok daha yukarıda", "Göğüs boşluğunda"], a: "Sağ böbreğin üstünde büyük karaciğer bulunur. Bu yüzden sağ böbrek genellikle soldakinden biraz daha aşağıda yer alır." },
  { id: "p08-274", k: "Vücut", s: "Böbreğin içinde idrarın toplanıp üretere aktığı huni biçimli bölüme ne denir?", d: "Böbrek havuzu", y: ["Glomerül", "Mesane boynu"], a: "Nefronlardan gelen idrar küçük kanallarla böbrek havuzunda toplanır ve buradan üretere geçer." },
  { id: "p08-275", k: "Vücut", s: "Yirmi yaş dişleri dahil yetişkin bir insanda kaç diş bulunur?", d: "32", y: ["28", "36"], a: "Yetişkin ağzında 32 kalıcı diş bulunur. Yirmi yaş dişleri bazı insanlarda hiç çıkmaz, bu yüzden sayı 28 de olabilir." },
  { id: "p08-276", k: "Vücut", s: "Bir çocukta toplam kaç süt dişi bulunur?", d: "20", y: ["12", "32"], a: "Süt dişleri her çenede 10 olmak üzere 20 tanedir. Genellikle 6 yaş civarında dökülmeye başlar." },
  { id: "p08-277", k: "Vücut", s: "İnsan vücudunun en sert maddesi hangisidir?", d: "Diş minesi", y: ["Uyluk kemiği", "Tırnak"], a: "Diş minesinin çok büyük kısmı mineraldir. Bu yüzden kemikten bile serttir." },
  { id: "p08-278", k: "Vücut", s: "Diş minesinin hemen altındaki, dişin büyük kısmını oluşturan tabaka hangisidir?", d: "Dentin", y: ["Pulpa", "Sement"], a: "Dentin mineden daha yumuşak, kemiğe benzer bir dokudur. İçinde pulpaya uzanan çok ince kanalcıklar bulunur." },
  { id: "p08-279", k: "Vücut", s: "Dişin sinir ve damarlarını içeren en iç kısmına ne denir?", d: "Pulpa (diş özü)", y: ["Mine", "Dentin"], a: "Pulpa dişi besler ve duyarlılığını sağlar. Çürük pulpaya ulaşınca şiddetli diş ağrısı olabilir." },
  { id: "p08-280", k: "Vücut", s: "Diş kökünün dış yüzeyini kaplayan tabakaya ne denir?", d: "Sement", y: ["Mine", "Pulpa"], a: "Sement kökü kaplar ve dişi çene kemiğine bağlayan liflerin tutunma yeridir." },
  { id: "p08-281", k: "Vücut", s: "Bebeklerde ilk süt dişi genellikle ne zaman çıkar?", d: "6. ay civarında", y: ["Doğumda", "3 yaşında"], a: "İlk süt dişi çoğu bebekte 6. ay civarında, genellikle alt ön kesicilerden çıkar. Zamanlama bebekten bebeğe değişebilir." },
  { id: "p08-282", k: "Vücut", s: "Kalıcı dişlerden ilk çıkanlardan olan 6 yaş dişleri hangi dişlerdir?", d: "Birinci büyük azılar", y: ["Köpek dişleri", "Yirmi yaş dişleri"], a: "Birinci büyük azılar 6 yaş civarında süt dişlerinin arkasından çıkar. Hiçbir süt dişinin yerine geçmedikleri için süt dişi sanılabilir." },
  { id: "p08-283", k: "Vücut", s: "Yirmi yaş dişleri aslında hangi dişlerdir?", d: "Üçüncü büyük azılar", y: ["Kesici dişler", "Küçük azılar"], a: "Yirmi yaş dişleri ağzın en arkasında çıkar, genellikle 17-25 yaşları arasında. Bazı insanlarda hiç oluşmaz." },
  { id: "p08-284", k: "Vücut", s: "Ön kesici dişlerin başlıca görevi nedir?", d: "Isırıp kesmek", y: ["Öğütmek", "Ezip yırtmak"], a: "Kesici dişlerin keskin ve yassı kenarları besini ısırarak koparmaya uygundur." },
  { id: "p08-285", k: "Vücut", s: "Büyük azı dişlerinin başlıca görevi nedir?", d: "Besini öğütmek", y: ["Besini kesmek", "Besini delmek"], a: "Azı dişlerinin geniş ve tümsekli yüzeyleri, değirmen taşı gibi besini ezip öğütür." },
  { id: "p08-286", k: "Vücut", s: "Üst köpek dişine halk arasında ne ad verilir?", d: "Göz dişi", y: ["Akıl dişi", "Süt dişi"], a: "Üst köpek dişinin kökü çok uzundur ve göz çukurunun altına doğru uzanır. Bu yüzden halk arasında göz dişi denir." },
  { id: "p08-287", k: "Vücut", s: "Yetişkinde bir çenenin bir yarısında kaç kalıcı diş bulunur?", d: "8", y: ["6", "10"], a: "Her yarı çenede 2 kesici, 1 köpek dişi, 2 küçük azı ve 3 büyük azı bulunur. 4 x 8 = 32 eder." },
  { id: "p08-288", k: "Vücut", s: "Süt dişleri arasında bulunmayan diş türü hangisidir?", d: "Küçük azılar", y: ["Kesiciler", "Köpek dişleri"], a: "Süt dişlerinde kesici, köpek ve azı dişleri vardır. Küçük azılar ancak kalıcı dişlerle, süt azılarının yerine çıkar." },
  { id: "p08-289", k: "Vücut", s: "Diş çürüğü esas olarak nasıl oluşur?", d: "Bakterilerin şekerden ürettiği asitle", y: ["Soğuk içeceklerle", "Güçlü çiğnemeyle"], a: "Ağızdaki bakteriler şekerleri işleyip asit üretir. Bu asit mineden mineral kaybettirerek çürüğe yol açar." },
  { id: "p08-290", k: "Vücut", s: "Florürün dişler üzerindeki etkisi nedir?", d: "Mineyi asitlere karşı güçlendirir", y: ["Mineyi yumuşatır", "Dişleri beyazlatır"], a: "Florür minenin kristal yapısına katılarak onu asitlere karşı daha dayanıklı hale getirir." },
  { id: "p08-291", k: "Vücut", s: "Çürükle kaybolan diş minesi vücut tarafından yeniden yapılabilir mi?", d: "Hayır, mine hücreleri artık yoktur", y: ["Evet, her yıl yenilenir", "Evet, kemik gibi kaynar"], a: "Mineyi yapan hücreler diş çıktıktan sonra kaybolur. Erken evrede mineral kazanılabilse de kaybolan mine dokusu yeniden oluşmaz." },
  { id: "p08-292", k: "Vücut", s: "Diş taşı nedir?", d: "Sertleşmiş diş plağı", y: ["Kırılmış mine parçası", "Çene kemiği çıkıntısı"], a: "Temizlenmeyen plak tükürükteki minerallerle sertleşir ve diş taşına dönüşür. Diş taşı fırçayla çıkmaz." },
  { id: "p08-293", k: "Vücut", s: "Dişi çene kemiğindeki yuvasına bağlayan yapıya ne denir?", d: "Diş bağı (periodontal bağ)", y: ["Aşil tendonu", "Gırtlak kapağı"], a: "Bu bağ dişi yuvasında asılı tutar ve çiğneme kuvvetini yumuşatır. Bu yüzden dişler çok az da olsa oynayabilir." },
  { id: "p08-294", k: "Vücut", s: "Süt dişlerinin taslakları ne zaman oluşmaya başlar?", d: "Doğumdan önce", y: ["Ergenlikte", "5 yaşında"], a: "Süt dişlerinin taslakları anne karnında oluşmaya başlar. Doğumda çene kemiğinin içinde hazır bekler." },
  { id: "p08-295", k: "Vücut", s: "Tükürüğün dişlere faydası nedir?", d: "Asitleri nötrleyip mineyi korur", y: ["Mineyi eritir", "Dişleri uzatır"], a: "Tükürük besin artıklarını yıkar, asitleri nötrler ve mineye kalsiyum ile fosfat sağlar." },
  { id: "p08-296", k: "Vücut", s: "Dişin diş etinin üstünde kalan görünen kısmına ne denir?", d: "Kron (taç)", y: ["Kök", "Pulpa"], a: "Kron mineyle kaplıdır. Diş eti altında kalan kök kısmı ise sementle kaplıdır." },
  { id: "p08-297", k: "Vücut", s: "Süt dişleri dökülürken köklerine ne olur?", d: "Alttan gelen kalıcı diş kökü eritir", y: ["Kök kemiğe dönüşür", "Kök diş etinde kalır"], a: "Kalıcı diş yükseldikçe süt dişinin kökü erir. Kökü kalmayan süt dişi gevşer ve düşer." },
];
